= 'human-edit')\n      // A version's baseVersionId chain always terminates at ordinal 1, and\n      // `commitStyleEdit` only ever appends onto an existing artifact\n      // (`createArtifact` always supplies its own contentOrigin, never\n      // `commitStyleEdit`'s hardcoded 'human-edit') — so ordinal 1 is never\n      // itself human-edit, and this findLast always resolves.\n      /* v8 ignore next 3 */\n      if (sourceVersion === undefined) {\n        throw new ScienceRuntimeError('CHART_NOT_ADDRESSABLE', 'Chart source run is unavailable; rerun the code to regenerate this figure')\n      }\n      const sourceFigureState = await store.getFigureState(projectId, sourceVersion.versionId)\n      // `parentChart.figureKey` chains back, unchanged, to whichever\n      // run-auto version's own successful chart extraction first produced\n      // it (every step here and in capture.ts's figureState copies the\n      // prior figureKey verbatim) — so that same ancestor's figure_state\n      // row still exists whenever `sourceVersion` does.\n      /* v8 ignore next 3 */\n      if (sourceFigureState === undefined) {\n        throw new ScienceRuntimeError('CHART_NOT_ADDRESSABLE', 'Chart source run is unavailable; rerun the code to regenerate this figure')\n      }\n      const sourceChart = decodeScienceChartState(JSON.parse(sourceFigureState.stateJson))\n      if (sourceChart.figureKey !== parentChart.figureKey) {\n        throw new ScienceRuntimeError('CHART_NOT_ADDRESSABLE', 'Chart source run is unavailable; rerun the code to regenerate this figure')\n      }\n      /* v8 ignore next 3 -- a run-auto version's producer always carries the run id that produced it */\n      if (sourceVersion.producerRunId === undefined) {\n        throw new ScienceRuntimeError('CHART_NOT_ADDRESSABLE', 'Chart source run is unavailable; rerun the code to regenerate this figure')\n      }\n      const sourceRunId = ScienceRunId(sourceVersion.producerRunId)\n      const sourceRun = projection.runs.find(candidate => candidate.runId === sourceRunId)\n      const environment = projection.environment\n      // The durable Science invariant requires every run-origin artifact to reference a terminal\n      // run under an applied environment revision.\n      /* v8 ignore next 3 */\n      if (sourceRun === undefined || environment === null || environment.status !== 'applied') {\n        throw new ScienceRuntimeError('CHART_NOT_ADDRESSABLE', 'Chart source run is unavailable; rerun the code to regenerate this figure')\n      }\n      const language: ScienceLanguage = parentChart.runtime === 'matplotlib' ? 'python' : 'r'\n      editLanguage = language\n      if (sourceRun.language !== language) {\n        throw new ScienceRuntimeError('CHART_NOT_ADDRESSABLE', 'Chart runtime does not match its source run language')\n      }\n      const scratchPreparation = await materializeSessionScratch(this.dshHome, request.session)\n      sessionScratch = scratchPreparation.scratch\n      const kernel = await this.acquireKernel(request.session, language, environment, sessionScratch, lease.control)\n      this.kernels.disarmIdleTimer(request.session, language)\n\n      const cumulativeOps = [...parentChart.ops, ...request.ops]\n      const failedOffset = parentChart.ops.length\n      let application = await this.applyChartInKernel(\n        kernel.process,\n        sourceRunId,\n        parentChart.figureKey,\n        cumulativeOps,\n        parentChart.png.dpi,\n        planRunScratch(sessionScratch, sourceRunId, language).directory,\n        lease.control.signal,\n      )\n      if (application.kind === 'not-registered') {\n        const sourceScratch = planRunScratch(sessionScratch, sourceRunId, language)\n        let sourceBytes: Uint8Array\n        try {\n          sourceBytes = await readFile(sourceScratch.source)\n        } catch (error) {\n          throw new ScienceRuntimeError(\n            'CHART_NOT_ADDRESSABLE',\n            'Chart source scratch is unavailable; rerun the code to regenerate this figure',\n            { cause: error },\n          )\n        }\n        const prepared = await prepareRunArtifacts(\n          projection,\n          this.ctx.scienceArtifactStore,\n          projectId,\n          sourceRun.inputs,\n          undefined,\n          undefined,\n          this.inputMaxFilesPerRun,\n          this.inputMaxBytesPerRun,\n          lease.control.signal,\n        )\n        replayScratch = await createRunScratch(\n          sessionScratch,\n          ScienceRunId(`replay-${randomUUID()}`),\n          language,\n          sourceBytes,\n        )\n        await materializeRunInputs(replayScratch, prepared.materialized)\n        this.assertPrepublication(request.session, lease.control)\n        usingReplay = true\n        replayKernel = await this.kernels.startIsolated(\n          request.session, language, environment, await createIsolatedKernelScratch(replayScratch), lease.control.signal,\n        )\n        this.assertPrepublication(request.session, lease.control)\n        const replayOutcome = await settleKernelExecution(lease.control, replayKernel, {\n          runId: sourceRunId,\n          sourcePath: replayScratch.source,\n          cwd: replayScratch.directory,\n          stdoutPath: replayScratch.stdout,\n          stderrPath: replayScratch.stderr,\n          artifactDir: replayScratch.artifacts,\n          inputDir: replayScratch.inputs,\n        })\n        this.assertPrepublication(request.session, lease.control)\n        if (replayOutcome.status !== 'success') {\n          throw new ScienceRuntimeError('CHART_NOT_ADDRESSABLE', 'Chart source replay failed; rerun the code to regenerate this figure')\n        }\n        application = await this.applyChartInKernel(\n          replayKernel,\n          sourceRunId,\n          parentChart.figureKey,\n          cumulativeOps,\n          parentChart.png.dpi,\n          replayScratch.directory,\n          lease.control.signal,\n        )\n      }\n      if (application.kind === 'not-registered') {\n        throw new ScienceRuntimeError('CHART_NOT_ADDRESSABLE', 'Chart source replay did not register the figure')\n      }\n      if (application.failedOps.some(failed => failed.index < failedOffset)) {\n        throw new ScienceRuntimeError('CHART_NOT_ADDRESSABLE', 'Chart committed edits could not be reconstructed; rerun the code to regenerate this figure')\n      }\n      const failedOps = application.failedOps\n        .filter(failed => failed.index >= failedOffset)\n        .map(failed => ({ index: failed.index - failedOffset, reason: failed.reason }))\n      const failedIndices = new Set(failedOps.map(failed => failed.index))\n      const successfulOps = request.ops.filter((_, index) => !failedIndices.has(index))\n      if (commit && successfulOps.length === 0) {\n        // Every op's own resolution reason (e.g. set_font's font_not_found,\n        // which never fails for element-resolution reasons) rides in the\n        // thrown message: the failedOps list itself only reaches the caller\n        // on a non-throwing partial-failure result, so a whole-request\n        // rejection would otherwise discard why each op failed and leave\n        // only this generic summary. See edit-message.ts's\n        // translateChartRuntimeError and the panel's `style.failed` render.\n        const detail = failedOps\n          // oxlint-disable-next-line typescript/no-non-null-assertion -- failed.index indexes request.ops (see successfulOps above)\n          .map(failed => `op ${String(failed.index + 1)} ${request.ops[failed.index]!.op} — ${failed.reason}`)\n          .join('; ')\n        throw new ScienceRuntimeError('CHART_ELEMENT_NOT_FOUND', `No chart edit operation applied: ${detail}`)\n      }\n      const chart = decodeScienceChartState({\n        ...application.chart,\n        figureKey: parentChart.figureKey,\n        ops: [...parentChart.ops, ...successfulOps],\n      })\n      this.assertPrepublication(request.session, lease.control)\n      if (!commit) {\n        previewReady = true\n        return { png: application.png, chart, failedOps }\n      }\n      // Human-edit provenance (T2§6): the new version's base is the exact\n      // parent version, its content_origin is 'human-edit', its\n      // environment* fields are ASSIGNED from the parent's own store-read\n      // values (never re-validated against a fold check — the store row is\n      // already the fact), and it carries no run/tool-call producer fields\n      // of its own beyond `producerTurn` — the session's last started turn\n      // when this method was called, captured before the replay/kernel work\n      // below so an edit applied during an idle gap between turns\n      // attributes to the turn that was current then.\n      const stored = await store.appendVersion(projectId, parent.artifactId, {\n        producerSessionId: request.session.id,\n        data: application.png,\n        mediaType: 'image/png',\n        contentOrigin: 'human-edit',\n        baseVersionId: parent.versionId,\n        ...producerTurn === undefined ? {} : { producerTurn },\n        ...parentRecord.environmentRevision === undefined ? {} : { environmentRevision: parentRecord.environmentRevision },\n        ...parentRecord.environmentFingerprint === undefined ? {} : { environmentFingerprint: parentRecord.environmentFingerprint },\n        figureState: { figureKey: chart.figureKey, dpi: chart.png.dpi, stateJson: JSON.stringify(chart) },\n      })\n      // Title/caption are inherited verbatim from the parent's current\n      // presentation (a separate annotation, not a `versions` column — T1\n      // dropped title/caption from `createArtifact`/`appendVersion` entirely).\n      await store.annotateVersion(projectId, stored.versionId, {\n        actor: 'human',\n        sessionId: request.session.id,\n        title: parent.title,\n        caption: parent.caption ?? null,\n      })\n      const artifact: ScienceArtifactVersion = {\n        artifactId: parent.artifactId,\n        logicalName: parent.logicalName,\n        version: stored.ordinal,\n        title: parent.title,\n        ...parent.caption === undefined ? {} : { caption: parent.caption },\n        projectId,\n        versionId: stored.versionId,\n        sha256: stored.sha256,\n        seenAt: Date.now(),\n      }\n      this.assertPrepublication(request.session, lease.control)\n      this.appendArtifactSavedOrMarkOrphan(request.session, projectId, stored.versionId, artifact)\n      return { artifact, failedOps }\n    } catch (error) {\n      if (!usingReplay && (error instanceof KernelProtocolError || error instanceof KernelExitedError)) {\n        // applyChartInKernel is reached only after editLanguage is assigned.\n        /* v8 ignore next */\n        if (editLanguage !== undefined) await this.kernels.retireForEscalation(request.session, editLanguage)\n      }\n      if (lease.control.signal.aborted) throw this.prepublicationError(lease.control, undefined)\n      throw error instanceof ScienceRuntimeError ? error : this.prepublicationError(lease.control, error)\n    } finally {\n      try {\n        if (replayKernel !== undefined) {\n          const quiescence = await replayKernel.end('chart-replay-finished')\n          if (!quiescence.quiescent) await quiescence.eventualQuiescence\n        }\n        if (sessionScratch !== undefined && replayScratch !== undefined) {\n          await removeUnpublishedRunScratch(sessionScratch, replayScratch)\n        }\n      } finally {\n        if (editLanguage !== undefined) this.kernels.resetIdleTimer(request.session, editLanguage)\n        this.leases.release(lease)\n      }\n      if (previewReady) this.assertPrepublication(request.session, lease.control)\n    }\n  }\n\n  /** Exchange one chart request through private files and decode its exact result fields. */\n  private async applyChartInKernel(\n    kernel: KernelProcess,\n    runId: ScienceRunId,\n    figureKey: string,\n    ops: readonly ScienceChartOp[],\n    dpi: number,\n    directory: string,\n    signal: AbortSignal,\n  ): Promise<\n    | { readonly kind: 'not-registered' }\n    | { readonly kind: 'applied'; readonly chart: Record<string, unknown>; readonly failedOps: readonly ScienceChartFailedOp[]; readonly png: Uint8Array }\n  > {\n    const token = randomUUID()\n    const requestPath = join(directory, `chart-apply-${token}-request.json`)\n    const resultPath = join(directory, `chart-apply-${token}-result.json`)\n    const outputPath = join(directory, `chart-apply-${token}.png`)\n    try {\n      await writeFile(requestPath, JSON.stringify({ figureKey, ops, outputPath, dpi }), { encoding: 'utf8', mode: 0o600, flag: 'wx' })\n      const frame = await kernel.applyChart({ runId, requestPath, resultPath, timeoutMs: this.chartExtractTimeoutMs, signal })\n      if (frame.status === 'error' && frame.detail === 'not_registered') return { kind: 'not-registered' }\n      if (frame.status === 'error') throw new Error(`science-runtime: chart application failed: ${frame.detail}`)\n      const root = plainRecord(JSON.parse(await readFile(resultPath, 'utf8')))\n      const chart = root === undefined ? undefined : plainRecord(root['chart'])\n      const failed = root?.['failedOps']\n      if (root === undefined || chart === undefined || !Array.isArray(failed)\n        || Object.keys(root).sort().join(',') !== 'chart,failedOps') {\n        throw new Error('science-runtime: chart application result must contain exact chart and failedOps fields')\n      }\n      const failedOps = failed.map((value) => {\n        const candidate = plainRecord(value)\n        if (candidate === undefined || Object.keys(candidate).sort().join(',') !== 'index,reason'\n          || !Number.isSafeInteger(candidate['index']) || (candidate['index'] as number) < 0\n          || typeof candidate['reason'] !== 'string') {\n          throw new Error('science-runtime: chart application failedOps entry is invalid')\n        }\n        return { index: candidate['index'] as number, reason: candidate['reason'] }\n      })\n      return { kind: 'applied', chart, failedOps, png: await readFile(outputPath) }\n    } finally {\n      await Promise.allSettled([requestPath, resultPath, outputPath].map(path => unlink(path)))\n    }\n  }\n\n  /**\n   * Re-commit an existing artifact version's exact store content reference\n   * with a curated title and caption: metadata-only, appending one new\n   * `version_annotations` row (`annotateVersion`) rather than opening a new\n   * version whose bytes would repeat their predecessor's. The store's\n   * annotation write is the sole authority for this metadata edit's own\n   * provenance (`actor: 'model'`, `sessionId`, `toolCallId`,\n   * `requestHeaderSeq`) — this operation never rebuilds a full version value\n   * and never lets the curating call's identity stand in for the content's\n   * own producer. A vetoed append after the store update leaves the store\n   * curated with no matching event — accepted metadata decay, resolved by\n   * the fold's own value staying the projection authority. A committed\n   * event is never rolled back because a later step fails; there is no\n   * later step here that can fail after the append.\n   * @param request - Exact live Session, target logical artifact (and optional version), title/caption, and cancellation.\n   * @returns The durable curated version this operation committed.\n   */\n  async annotateArtifact(request: AnnotateScienceArtifactRequest): Promise<ScienceArtifactVersion> {\n    const projection = this.assertSession(request.session)\n    const lease = this.reserve(request.session, request.signal, this.timeoutMs)\n    try {\n      this.assertPrepublication(request.session, lease.control)\n      const target = await this.resolveAnnotateTarget(projection, request)\n      const store = this.ctx.scienceArtifactStore\n      const currentVersion = await store.getVersion(target.projectId, target.versionId)\n      /* v8 ignore next 3 -- projection already resolved this versionId; a missing store row is a durable invariant violation */\n      if (currentVersion === undefined) {\n        throw new Error('science-runtime: annotate target no longer identifies a committed store version')\n      }\n      if (currentVersion.contentOrigin === 'human-edit') {\n        throw new ScienceRuntimeError(\n          'ARTIFACT_NOT_CURATABLE',\n          `artifact ${JSON.stringify(request.logicalName)} version ${String(target.version)} exists but is a direct human style edit and cannot be curated; `\n            + 'edit its content through a new run (run_python/run_r against it as an edit_of baseline) or the viewer\\'s style editor instead',\n        )\n      }\n      this.assertPrepublication(request.session, lease.control)\n      try {\n        await store.annotateVersion(target.projectId, target.versionId, {\n          actor: 'model',\n          sessionId: request.session.id,\n          toolCallId: request.toolCallId,\n          requestHeaderSeq: request.requestHeaderSeq,\n          title: request.title,\n          caption: request.caption ?? null,\n        })\n      } catch (error) {\n        if (error instanceof ProjectArtifactStoreError && error.code === 'ANNOTATION_TOOL_CALL_REUSED') {\n          throw new ScienceRuntimeError(\n            'ARTIFACT_ANNOTATE_TOOL_CALL_REUSED',\n            `toolCallId ${JSON.stringify(request.toolCallId)} already authorized a prior artifact annotation and cannot authorize another`,\n            { cause: error },\n          )\n        }\n        throw error\n      }\n      const artifact: ScienceArtifactVersion = {\n        artifactId: target.artifactId,\n        logicalName: request.logicalName,\n        // Curation is metadata over content the session already holds, so it\n        // supersedes the version it names instead of opening one whose bytes\n        // would be identical to its predecessor's.\n        version: target.version,\n        title: request.title,\n        ...request.caption === undefined ? {} : { caption: request.caption },\n        projectId: target.projectId,\n        versionId: target.versionId,\n        sha256: currentVersion.sha256,\n        seenAt: Date.now(),\n      }\n      this.assertPrepublication(request.session, lease.control)\n      this.appendArtifactSavedOrMarkOrphan(request.session, target.projectId, target.versionId, artifact)\n      return artifact\n    } catch (error) {\n      throw this.prepublicationError(lease.control, error)\n    } finally {\n      this.leases.release(lease)\n    }\n  }\n\n  /**\n   * Duplicate one existing artifact version into a brand-new logical\n   * artifact in the same project. Content-addressed bytes are reused (the\n   * store's blob admission is idempotent by digest, so re-admitting the\n   * source's own bytes never duplicates them on disk); provenance is a\n   * fresh fact this session originates, not a copy of the source's own\n   * producer — `baseVersionId` names the source explicitly instead. A\n   * viewer operation: no authorizing tool call, so `session.append` records\n   * only the store reference and the presentation snapshot the store just\n   * committed; the new version's `producerTurn` is the session's last\n   * started turn at the moment this method was called, so a save-as\n   * during an idle gap between turns attributes to the turn that was\n   * current then, never to whichever turn is newest by the time the store\n   * write commits.\n   * @param request - Exact Session, the store version to duplicate, and the new logical name.\n   * @returns The durable new artifact version this operation appended.\n   * @throws {@link ScienceRuntimeError} (`ARTIFACT_VERSION_NOT_FOUND`) when\n   *   `sourceVersionId` does not identify a committed version in the\n   *   session's owning project, or (`ARTIFACT_LOGICAL_NAME_CONFLICT`) when\n   *   `newLogicalName` is already used in that project.\n   */\n  async saveArtifactAs(request: SaveScienceArtifactAsRequest): Promise<ScienceArtifactVersion> {\n    const projection = this.assertSession(request.session)\n    const producerTurn = projection.trace.turns.at(-1)?.turn\n    const lease = this.reserve(request.session, request.signal, this.timeoutMs)\n    try {\n      this.assertPrepublication(request.session, lease.control)\n      const projectId = await this.sessionProject(request.session)\n      const store = this.ctx.scienceArtifactStore\n      const source = await store.getVersion(projectId, request.sourceVersionId)\n      if (source === undefined) {\n        throw new ScienceRuntimeError(\n          'ARTIFACT_VERSION_NOT_FOUND',\n          `version ${JSON.stringify(request.sourceVersionId)} does not identify a committed version in this project`,\n        )\n      }\n      const sourceArtifact = await store.getArtifact(projectId, source.artifactId)\n      /* v8 ignore next 3 -- a version's own store row always names an artifact row the same store still holds */\n      if (sourceArtifact === undefined) {\n        throw new Error('science-runtime: save-as source version no longer identifies a committed artifact')\n      }\n      const sourceFigureState = await store.getFigureState(projectId, source.versionId)\n      const data = await store.readBlob(projectId, source.sha256)\n      this.assertPrepublication(request.session, lease.control)\n      let created: Awaited<ReturnType<typeof store.createArtifact>>\n      try {\n        created = await store.createArtifact(projectId, {\n          logicalName: request.newLogicalName,\n          kind: sourceArtifact.kind,\n          originSessionId: request.session.id,\n          data,\n          mediaType: source.mediaType,\n          contentOrigin: source.contentOrigin,\n          baseVersionId: source.versionId,\n          ...producerTurn === undefined ? {} : { producerTurn },\n          ...source.environmentRevision === undefined ? {} : { environmentRevision: source.environmentRevision },\n          ...source.environmentFingerprint === undefined ? {} : { environmentFingerprint: source.environmentFingerprint },\n          ...sourceFigureState === undefined ? {} : {\n            figureState: { figureKey: sourceFigureState.figureKey, dpi: sourceFigureState.dpi, stateJson: sourceFigureState.stateJson },\n          },\n        })\n      } catch (error) {\n        if (error instanceof ProjectArtifactStoreError && error.code === 'LOGICAL_NAME_CONFLICT') {\n          throw new ScienceRuntimeError(\n            'ARTIFACT_LOGICAL_NAME_CONFLICT',\n            `an artifact named ${JSON.stringify(request.newLogicalName)} already exists in this project`,\n            { cause: error },\n          )\n        }\n        throw error\n      }\n      // Title/caption are inherited verbatim from the source's current\n      // presentation (a separate annotation, not a `versions` column — T1\n      // dropped title/caption from `createArtifact` entirely).\n      await store.annotateVersion(projectId, created.version.versionId, {\n        actor: 'human',\n        sessionId: request.session.id,\n        title: source.title ?? request.newLogicalName,\n        caption: source.caption ?? null,\n      })\n      const artifact: ScienceArtifactVersion = {\n        artifactId: created.artifact.artifactId,\n        logicalName: request.newLogicalName,\n        version: created.version.ordinal,\n        title: source.title ?? request.newLogicalName,\n        ...source.caption === undefined ? {} : { caption: source.caption },\n        projectId,\n        versionId: created.version.versionId,\n        sha256: created.version.sha256,\n        seenAt: Date.now(),\n      }\n      this.assertPrepublication(request.session, lease.control)\n      this.appendArtifactSavedOrMarkOrphan(request.session, projectId, created.version.versionId, artifact)\n      return artifact\n    } catch (error) {\n      throw this.prepublicationError(lease.control, error)\n    } finally {\n      this.leases.release(lease)\n    }\n  }\n\n  /**\n   * Resolve the exact source version `request` names (its exact `version`,\n   * or the logical artifact's latest version) from this session's own live\n   * projection.\n   * @param projection - exact live Science projection.\n   * @param request - the annotate request naming the target logical artifact.\n   * @returns the resolved target version's session-visible identity.\n   * @throws {@link ScienceRuntimeError} (`ARTIFACT_NOT_FOUND`) when `logicalName`\n   *   (or its named `version`) does not exist in this session.\n   */\n  private async resolveAnnotateTarget(\n    projection: ScienceProjection,\n    request: AnnotateScienceArtifactRequest,\n  ): Promise<ScienceArtifactVersion> {\n    const logical = projection.artifacts.filter(candidate => candidate.logicalName === request.logicalName)\n    const latest = logical.at(-1)\n    if (latest === undefined) {\n      const retainedLocation = await this.findRetainedRasterLocation(request.session, projection, request.logicalName)\n      throw new ScienceRuntimeError(\n        'ARTIFACT_NOT_FOUND',\n        retainedLocation === 'artifact-dir'\n          ? `file ${JSON.stringify(request.logicalName)} exists in retained run output but was not captured; `\n            + `run the code that writes it again with raster_artifacts: [${JSON.stringify(request.logicalName)}], then call annotate_artifact again`\n          : retainedLocation === 'run-root'\n            ? `file ${JSON.stringify(request.logicalName)} exists in retained run output but was written outside SCIENCE_ARTIFACT_DIR; `\n              + `run the code that writes it again, save it under SCIENCE_ARTIFACT_DIR, and declare it with raster_artifacts: [${JSON.stringify(request.logicalName)}], then call annotate_artifact again`\n            : `no artifact named ${JSON.stringify(request.logicalName)} exists in this session`,\n      )\n    }\n    const source = request.version === undefined ? latest : logical.find(candidate => candidate.version === request.version)\n    if (source === undefined) {\n      const available = logical.map(candidate => candidate.version).join(', ')\n      throw new ScienceRuntimeError(\n        'ARTIFACT_NOT_FOUND',\n        `artifact ${JSON.stringify(request.logicalName)} has no version ${JSON.stringify(request.version)}. Available: ${available}.`,\n      )\n    }\n    return source\n  }\n\n  /**\n   * Check the `annotateDiagnosticMaxRuns` most recent retained runs for a\n   * same-named PNG solely to improve an `annotate_artifact` not-found\n   * diagnostic. Every run owns a distinct `SCIENCE_ARTIFACT_DIR`, so finding\n   * the file never imports or captures it: the model must execute code that\n   * writes it into a new run. A session with no retained scratch (or one this\n   * bound leaves unvisited) degrades to the generic not-found diagnostic.\n   * @param session - exact live Session that owns the retained scratch.\n   * @param projection - current Science projection whose run ids identify directories to inspect.\n   * @param logicalName - missing logical artifact name requested for curation.\n   * @returns `'artifact-dir'` when a run has the file undeclared under\n   *   `SCIENCE_ARTIFACT_DIR`, `'run-root'` when a run instead has it in the\n   *   run's own scratch root (outside `SCIENCE_ARTIFACT_DIR` entirely), or\n   *   `'not-found'`.\n   */\n  private async findRetainedRasterLocation(\n    session: Session,\n    projection: ScienceProjection,\n    logicalName: string,\n  ): Promise<RetainedRasterLocation> {\n    let scratch: ScienceSessionScratch\n    try {\n      scratch = await planSessionScratch(this.dshHome, session)\n    } catch {\n      // Retained scratch is diagnostic evidence only; the projection already\n      // proved the curation target absent, so a planning failure cannot turn\n      // this metadata operation into a filesystem failure.\n      return 'not-found'\n    }\n    const recentRuns = projection.runs.toReversed().slice(0, this.annotateDiagnosticMaxRuns)\n    for (const run of recentRuns) {\n      const location = await this.findRunRetainedRasterLocation(scratch, run.runId, logicalName)\n      if (location !== 'not-found') return location\n    }\n    return 'not-found'\n  }\n\n  /**\n   * Inspect one retained run's `SCIENCE_ARTIFACT_DIR` and its own scratch\n   * root for an eligible same-named PNG. `capturablePngPaths` never throws —\n   * an unreadable directory at any depth degrades to an empty result inside\n   * `walkArtifactFiles`, not an exception — so this method has no catch of\n   * its own; the caller's `planSessionScratch` catch is the only fallible\n   * step in this diagnostic. An `'artifact-dir'` match means the model wrote\n   * the file but did not declare it in `raster_artifacts`; a `'run-root'`\n   * match (outside the run's two reserved `artifacts/` and `inputs/`\n   * subdirectories) means the model wrote the file outside\n   * `SCIENCE_ARTIFACT_DIR` entirely, so auto-capture never saw it regardless\n   * of declaration.\n   * @param scratch - the owning session's private scratch root.\n   * @param runId - one retained run's durable identifier.\n   * @param logicalName - missing logical artifact name requested for curation.\n   * @returns where the file was found for this run alone, or `'not-found'`.\n   */\n  private async findRunRetainedRasterLocation(\n    scratch: ScienceSessionScratch,\n    runId: ScienceRunId,\n    logicalName: string,\n  ): Promise<RetainedRasterLocation> {\n    const declaration = new Set([logicalName])\n    const artifactPaths = await capturablePngPaths(runArtifactDirectory(scratch, runId), 'declared', declaration)\n    if (artifactPaths.includes(logicalName)) return 'artifact-dir'\n    // Walking the run's whole scratch root also revisits its `artifacts/`\n    // and `inputs/` subdirectories, but only as their own nested relative\n    // paths (`artifacts/${logicalName}`, `inputs/${logicalName}`) — an exact\n    // match against the bare `logicalName` this diagnostic already failed to\n    // find directly under `SCIENCE_ARTIFACT_DIR` names only a file at the\n    // scratch root itself, never one already inside either reserved directory.\n    const rootPaths = await capturablePngPaths(runScratchDirectory(scratch, runId), 'always', EMPTY_RASTER_DECLARATION)\n    return rootPaths.includes(logicalName) ? 'run-root' : 'not-found'\n  }\n\n  /**\n   * Reserve a non-queuing exact Session lease without leaking a rejected timer.\n   * @param session - exact live Session that will own the reservation.\n   * @param signal - caller-owned cancellation signal.\n   * @param timeoutMs - caller-owned operation deadline; explicit rather than a\n   *   hidden default so a caller whose own operation legitimately runs\n   *   longer than {@link ScienceRuntime.timeoutMs} (`installPackages`'s\n   *   {@link ScienceRuntime.installTimeoutMs}) states its own bound.\n   */\n  private reserve(session: BindScienceEnvironmentRequest['session'], signal: AbortSignal, timeoutMs: number) {\n    const control = new OperationControl(signal, timeoutMs)\n    try {\n      return this.leases.reserve(session, control)\n    } catch (error) {\n      control.dispose()\n      throw error\n    }\n  }\n\n  /**\n   * Reserve `session` for a run, queueing behind any run/bind/annotate\n   * operation already holding this Session's lease instead of failing the\n   * caller outright. `run_python` and `run_r` issued in the same assistant\n   * step share one Session-wide lease (`startRun`'s durable open-run check\n   * and `KernelSet`'s own per-Session acquire discipline both require at\n   * most one Runtime operation in flight per Session — see `kernel-set.ts`'s\n   * module doc), so this lets whichever call arrives second get a genuine\n   * turn once the first vacates instead of racing `RUNTIME_BUSY` against\n   * whichever call's synchronous prefix reserved first — the outcome a\n   * caller cancelled mid-race would otherwise see reported as an opaque\n   * `Science Runtime operation was cancelled` with no `run-started` fact to\n   * explain it.\n   *\n   * Retries {@link reserve} each time the blocking lease settles; every\n   * retry constructs a fresh {@link OperationControl}, so a caller's own\n   * per-operation deadline starts counting from when it actually acquires\n   * the lease, not from when it started queueing. `signal` aborting while\n   * queued, or the Runtime entering disposal while queued, rejects before\n   * constructing any `OperationControl`, so a caller cancelled or preempted\n   * while only queued never touches Runtime state.\n   * @param session - exact live Session that will own the reservation.\n   * @param signal - caller-owned cancellation signal.\n   * @param timeoutMs - caller-owned operation deadline passed to each retry's\n   *   fresh {@link reserve} call; see that method's own parameter doc.\n   * @returns the granted lease.\n   */\n  private async reserveQueued(\n    session: BindScienceEnvironmentRequest['session'],\n    signal: AbortSignal,\n    timeoutMs: number,\n  ): Promise<RuntimeLease> {\n    for (;;) {\n      if (signal.aborted) {\n        throw new ScienceRuntimeError('OPERATION_CANCELLED', 'Science Runtime operation was cancelled', { cause: signal.reason })\n      }\n      if (this.disposing) throw new ScienceRuntimeError('SERVICE_DISPOSING', 'Science Runtime is disposing')\n      try {\n        return this.reserve(session, signal, timeoutMs)\n      } catch (error) {\n        // LeaseRegistry.reserve's only throw is the RUNTIME_BUSY rejection\n        // this loop retries on (lifecycle.ts); a different shape is a\n        // defensive backstop, not a reachable production path.\n        /* v8 ignore next 2 */\n        if (!(error instanceof ScienceRuntimeError) || error.code !== 'RUNTIME_BUSY') throw error\n        // Synchronous throw-then-read with no `await` between them: the\n        // lease this RUNTIME_BUSY just named cannot have released yet.\n        // oxlint-disable-next-line typescript/no-non-null-assertion -- see above\n        const blocking = this.leases.blocking(session)!\n        await raceSettlementOrAbort(blocking.settlement, signal)\n      }\n    }\n  }\n\n  /**\n   * Resolve one configured profile without exposing the mutable configuration\n   * record. The requested id is fixed preset policy, never model or user\n   * input, so an unresolved id always means the deployment has not named a\n   * Conda prefix for it yet — the message names where to configure one\n   * instead of the internal profile-id vocabulary, because both a person\n   * reading it directly and a model relaying it to one need to act on it.\n   */\n  private profile(id: string): ConfiguredProfile {\n    const profile = this.profiles.get(id)\n    if (profile === undefined) {\n      throw new ScienceRuntimeError(\n        'PROFILE_NOT_CONFIGURED',\n        `no Conda prefix is configured for the Science environment profile ${JSON.stringify(id)} — `\n        + 'open Settings → Plugins → Science to configure one, then restart the Host',\n      )\n    }\n    return profile\n  }\n\n  /** Reject remote execution before observing or creating private Host scratch. */\n  private assertHostLocal(): void {\n    if (this.ctx.subprocess.executionWorld !== 'host-local') {\n      throw new ScienceRuntimeError('CONFINEMENT_UNAVAILABLE', 'Science private Host scratch requires a host-local subprocess provider')\n    }\n  }\n\n  /** Require an exact currently attached Science Session and its strict projection. */\n  private assertSession(session: BindScienceEnvironmentRequest['session']): ScienceProjection {\n    if (this.disposing) throw new ScienceRuntimeError('SERVICE_DISPOSING', 'Science Runtime is disposing')\n    if (this.ctx.sessions.get(session.id) !== session) {\n      throw new ScienceRuntimeError('SESSION_NOT_LIVE', 'Science Runtime requires the exact live Session object')\n    }\n    const projection = replayScience(session.snapshotEvents())\n    if (projection === null) {\n      throw new ScienceRuntimeError('ENVIRONMENT_NOT_READY', 'Science mode must be bound before Runtime operations')\n    }\n    return projection\n  }\n\n  /** Require an applied environment with no orphaned durable running run. */\n  private assertIdleAppliedEnvironment(\n    session: BindScienceEnvironmentRequest['session'],\n    control: OperationControl,\n  ): { projection: ScienceProjection; environment: ScienceEnvironmentBinding } {\n    this.assertPrepublication(session, control)\n    const projection = this.assertSession(session)\n    const environment = projection.environment\n    if (environment === null || environment.status !== 'applied') {\n      throw new ScienceRuntimeError('ENVIRONMENT_NOT_READY', 'Science Runtime requires an applied environment')\n    }\n    // The lease can be free while the durable log retains a run whose\n    // terminal event never committed before a crash or detach.\n    if (projection.runs.some(run => run.status === 'running')) {\n      throw new ScienceRuntimeError('RUNTIME_BUSY', 'Science Session already has an open run')\n    }\n    return { projection, environment }\n  }\n\n  /** Recheck exact liveness and caller-controlled pre-publication cancellation. */\n  private assertPrepublication(session: BindScienceEnvironmentRequest['session'], control: OperationControl): void {\n    if (this.ctx.sessions.get(session.id) !== session) {\n      throw new ScienceRuntimeError('SESSION_NOT_LIVE', 'Science Session detached before publication')\n    }\n    if (!control.signal.aborted) return\n    throw this.prepublicationError(control, undefined)\n  }\n\n  /** Translate a pre-publication cause without turning a capability failure into an event. */\n  private prepublicationError(control: OperationControl, error: unknown): Error {\n    if (error instanceof ScienceRuntimeError) return error\n    switch (control.cause) {\n      case 'timeout':\n        return new ScienceRuntimeError('OPERATION_TIMED_OUT', 'Science Runtime operation timed out', { cause: error })\n      case 'cancelled':\n      case 'service-disposed':\n      case 'session-detached':\n        return new ScienceRuntimeError('OPERATION_CANCELLED', 'Science Runtime operation was cancelled', { cause: error })\n      default:\n        return new ScienceRuntimeError('INFRASTRUCTURE_FAILURE', 'Science Runtime operation failed before publication', { cause: error })\n    }\n  }\n\n  /**\n   * Acquire this run's kernel: reuse a live matching-revision\n   * kernel, or spawn a fresh one — ending a stale-revision kernel first\n   * (`environment-rebound`). Translates every `KernelSet.acquire` rejection\n   * onto the pre-publication `ScienceRuntimeErrorCode` vocabulary. A\n   * rejection while `control`'s own signal is the cause (`control.cause` is\n   * set) goes through `prepublicationError` instead: passing\n   * `control.signal` into `KernelSet.acquire` means a fresh spawn can now be\n   * the thing that observed the abort, and that must still read as\n   * `OPERATION_TIMED_OUT`/`OPERATION_CANCELLED`, not a spawn failure.\n   * @param session - exact live Session that will own the kernel.\n   * @param language - requested interpreter language.\n   * @param environment - applied durable environment revision the kernel must serve.\n   * @param sessionScratch - the Session's already-materialized private scratch paths.\n   * @param control - this run's fused cancellation/timeout signal and first-cause record.\n   * @returns the acquired kernel process and its own session-local epoch.\n   */\n  private async acquireKernel(\n    session: Session,\n    language: ScienceLanguage,\n    environment: ScienceEnvironmentBinding,\n    sessionScratch: ScienceSessionScratch,\n    control: OperationControl,\n  ): Promise<AcquiredKernel> {\n    try {\n      return await this.kernels.acquire(session, language, environment, sessionScratch, control.signal)\n    } catch (error) {\n      if (control.cause !== undefined) throw this.prepublicationError(control, error)\n      throw this.kernelAcquisitionError(error, language)\n    }\n  }\n\n  /**\n   * Map a `KernelSet.acquire` rejection onto the pre-publication\n   * `ScienceRuntimeErrorCode` vocabulary. `KernelSetDetachedError`\n   * maps to `SESSION_NOT_LIVE`: it means this exact Session\n   * object already detached from the kernel set's registry — the same fact\n   * `assertPrepublication`'s synchronous liveness check, run immediately\n   * before every `acquireKernel` call with no intervening `await`, already\n   * guards against; reaching here at all would mean that check raced a\n   * detach in the same synchronous continuation, which cannot happen, so\n   * this classification is a defensive backstop naming the actual\n   * condition rather than a spawn failure. `KernelEpochRegressionError` is\n   * equally unreachable through this production allocator (`nextKernelEpoch`\n   * above): it derives strictly from the durable projection's own latest\n   * committed epoch, appendable only through the strictly-monotonic,\n   * append-only session log, so it can never return a value the live\n   * `KernelSet` entry's own `epochSeen` watermark (which only ever advances\n   * from that exact allocator's own prior return values) already exceeds —\n   * `kernel-set.spec.ts` proves the underlying `KernelSet` guard fires\n   * correctly against a deliberately misbehaving injected allocator instead.\n   */\n  private kernelAcquisitionError(error: unknown, language: ScienceLanguage): Error {\n    if (error instanceof KernelSetQuarantinedError) {\n      return new ScienceRuntimeError('RUNTIME_BUSY', 'Science kernel from a predecessor Session is still tearing down', { cause: error })\n    }\n    /* v8 ignore next 2 -- unreachable: see this method's own doc above. */\n    if (error instanceof KernelSetDetachedError) {\n      return new ScienceRuntimeError('SESSION_NOT_LIVE', 'Science Session detached before kernel acquisition', { cause: error })\n    }\n    /* v8 ignore next 2 -- unreachable: see this method's own doc above. */\n    if (error instanceof KernelEpochRegressionError) {\n      return new ScienceRuntimeError('INFRASTRUCTURE_FAILURE', 'Science kernel epoch allocation did not advance', { cause: error })\n    }\n    if (error instanceof KernelStartedAppendError) {\n      return new ScienceRuntimeError('INFRASTRUCTURE_FAILURE', 'Science kernel start fact could not be committed', { cause: error })\n    }\n    if (error instanceof ScienceRuntimeError) return error\n    return new ScienceRuntimeError(\n      'KERNEL_START_FAILED',\n      `Science ${language} kernel could not start: ${kernelStartCauseClass(error)}`,\n      { cause: error },\n    )\n  }\n\n  /**\n   * Settle a published kernel run: the RUN/DONE protocol exchange,\n   * bounded output-tail reads, terminal commit, auto-capture, and (when\n   * the run's classification requires it) background kernel retirement — while retaining the exact\n   * lease through commit or cleanup. Never proves subprocess-tree\n   * quiescence itself: that is `KernelSet`'s own concern for the kernel\n   * process, decoupled from this run's own terminal.\n   */\n  private async settlePublishedKernelRun(\n    lease: ReturnType<LeaseRegistry['reserve']>,\n    session: StartScienceRunRequest['session'],\n    projectId: ScienceProjectId,\n    runScratch: Awaited<ReturnType<typeof createRunScratch>>,\n    kernel: KernelProcess,\n    started: ReturnType<typeof startCandidate>,\n    preparedArtifacts: PreparedRunArtifacts,\n  ): Promise<ScienceRunResult> {\n    try {\n      const request: KernelExecuteRequest = {\n        runId: started.runId,\n        sourcePath: runScratch.source,\n        cwd: runScratch.directory,\n        stdoutPath: runScratch.stdout,\n        stderrPath: runScratch.stderr,\n        artifactDir: runScratch.artifacts,\n        inputDir: runScratch.inputs,\n      }\n      let outcome: KernelRunOutcome\n      try {\n        outcome = await settleKernelExecution(lease.control, kernel, request)\n      } catch (error) {\n        if (this.ctx.sessions.get(session.id) !== session) {\n          throw new ScienceRuntimeError('SESSION_NOT_LIVE', 'Science Session detached before terminal publication', { cause: error })\n        }\n        throw new ScienceRuntimeError('TERMINAL_COMMIT_FAILED', 'Science terminal value could not be prepared after kernel settlement', { cause: error })\n      }\n      let retireAfterChartExtraction = false\n      try {\n        const [stdout, stderr] = await Promise.all([readCaptureTail(runScratch.stdout), readCaptureTail(runScratch.stderr)])\n        const terminal = kernelRunTerminal(started, stdout, stderr, outcome.status, outcome.failureCode, outcome.outputDegraded)\n        if (this.ctx.sessions.get(session.id) !== session) {\n          throw new ScienceRuntimeError('SESSION_NOT_LIVE', 'Science Session detached before terminal publication')\n        }\n        try {\n          session.append('science/run-finished', { version: 1, run: terminal })\n        } catch (error) {\n          if (this.ctx.sessions.get(session.id) !== session) {\n            throw new ScienceRuntimeError('SESSION_NOT_LIVE', 'Science Session detached before terminal publication', { cause: error })\n          }\n          throw new ScienceRuntimeError('TERMINAL_COMMIT_FAILED', 'Science terminal fact could not be committed', { cause: error })\n        }\n        const extracted = outcome.retireKernel\n          ? { charts: new Map<string, ScienceChartState>(), retireKernel: false }\n          : await this.extractChartsAfterFinish(kernel, runScratch, terminal, preparedArtifacts.rasterArtifacts)\n        retireAfterChartExtraction = extracted.retireKernel\n        const capture = await this.captureAfterFinish(\n          session,\n          projectId,\n          runScratch,\n          terminal,\n          preparedArtifacts.editBaselines,\n          preparedArtifacts.rasterArtifacts,\n          extracted.charts,\n        )\n        return { terminal, stdout, stderr, ...capture }\n      } finally {\n        // Retire-vs-rearm derives from the settled run and chart protocol\n        // outcomes, so it must run on every exit from this block — including a\n        // thrown `readCaptureTail` or a vetoed `run-finished` append: a\n        // tainted kernel left unretired stays live with an\n        // unknown post-interrupt state for the next run to reuse, and a\n        // non-tainted kernel left unrearmed can never end `idle`.\n        if (outcome.retireKernel || retireAfterChartExtraction) {\n          // Fire-and-forget: never blocks this run's own settlement — a\n          // subsequent acquire() for this session drains any still-in-flight\n          // teardown internally (KernelSet.drain).\n          void this.kernels.retireForEscalation(session, started.language).catch((error: unknown) => {\n            this.ctx.logger.error(`science-runtime: kernel retirement failed for session \"${session.id}\": ${String(error)}`)\n          })\n        } else {\n          this.kernels.resetIdleTimer(session, started.language)\n        }\n      }\n    } finally {\n      this.leases.release(lease)\n    }\n  }\n\n  /**\n   * Ask a healthy kernel to extract chart state before the artifact walk.\n   * Every failure leaves the run terminal and ordinary capture intact.\n   * Protocol failure or timeout additionally retires the kernel because its\n   * request stream can no longer be trusted.\n   */\n  private async extractChartsAfterFinish(\n    kernel: KernelProcess,\n    runScratch: Awaited<ReturnType<typeof createRunScratch>>,\n    terminal: ScienceRunTerminal,\n    rasterArtifacts: PreparedRunArtifacts['rasterArtifacts'],\n  ): Promise<ExtractedChartsResult> {\n    let pngPaths: readonly string[]\n    try {\n      pngPaths = await capturablePngPaths(runScratch.artifacts, this.rasterCapture, rasterArtifacts)\n    } catch (error) {\n      /* v8 ignore start -- walkArtifactFiles absorbs per-directory filesystem failures and returns its safe partial result */\n      const message = `science-runtime: chart discovery failed for run \"${terminal.runId}\": ${String(error)}`\n      if (isCaptureFilesystemFailure(error)) this.ctx.logger.warn(message)\n      else this.ctx.logger.error(message)\n      return { charts: new Map(), retireKernel: false }\n      /* v8 ignore stop */\n    }\n    if (pngPaths.length === 0) return { charts: new Map(), retireKernel: false }\n\n    const requestPath = join(runScratch.directory, 'chart-extract-request.json')\n    const resultPath = join(runScratch.directory, 'chart-extract-result.json')\n    try {\n      await writeFile(requestPath, JSON.stringify({\n        artifactDir: runScratch.artifacts,\n        allow: this.rasterCapture === 'always' ? null : [...rasterArtifacts],\n        retainRuns: this.chartLiveRunsRetained,\n      }), { encoding: 'utf8', mode: 0o600, flag: 'wx' })\n      const frame = await kernel.extractCharts({\n        runId: terminal.runId,\n        requestPath,\n        resultPath,\n        timeoutMs: this.chartExtractTimeoutMs,\n      })\n      if (frame.status === 'error') {\n        this.ctx.logger.warn(`science-runtime: chart extraction failed for run \"${terminal.runId}\": ${frame.detail}`)\n        return { charts: new Map(), retireKernel: false }\n      }\n      const decoded: unknown = JSON.parse(await readFile(resultPath, 'utf8'))\n      const root = plainRecord(decoded)\n      const chartValues = root === undefined ? undefined : plainRecord(root['charts'])\n      const errors = root === undefined ? undefined : plainRecord(root['errors'])\n      if (root === undefined || chartValues === undefined || errors === undefined\n        || Object.keys(root).sort().join(',') !== 'charts,errors') {\n        throw new Error('chart result must contain exact charts and errors records')\n      }\n      for (const [path, detail] of Object.entries(errors)) {\n        if (typeof detail !== 'string') throw new Error('chart result errors must contain string values')\n        this.ctx.logger.warn(`science-runtime: chart ${JSON.stringify(path)} was not extracted for run \"${terminal.runId}\": ${detail}`)\n      }\n      const allowed = new Set(pngPaths)\n      const charts = new Map<string, ScienceChartState>()\n      for (const [path, extraction] of Object.entries(chartValues)) {\n        if (!allowed.has(path)) continue\n        try {\n          charts.set(path, decodeScienceChartState({\n            ...plainRecord(extraction),\n            figureKey: path,\n            ops: [],\n          }))\n        } catch (error) {\n          this.ctx.logger.warn(`science-runtime: chart ${JSON.stringify(path)} was invalid for run \"${terminal.runId}\": ${String(error)}`)\n        }\n      }\n      return { charts, retireKernel: false }\n    } catch (error) {\n      const retireKernel = error instanceof KernelProtocolError || error instanceof KernelExitedError\n      const message = `science-runtime: chart extraction failed for run \"${terminal.runId}\": ${String(error)}`\n      if (isCaptureFilesystemFailure(error)) this.ctx.logger.warn(message)\n      else this.ctx.logger.error(message)\n      return { charts: new Map(), retireKernel }\n    }\n  }\n\n  /**\n   * Auto-capture every eligible file in one just-finished run's artifact\n   * directory as the next version of its logical Science artifact. Runs\n   * once per run, immediately after its `science/run-finished` fact commits\n   * and while the run's lease is still held; a capture failure here is\n   * never a run failure — the terminal fact this run already committed\n   * stands regardless, symmetric to the accepted crash-between-commit-and-\n   * capture gap (capture.ts). Every failure is logged, not silently\n   * absorbed: an environmental fault (the artifact directory disappeared, a\n   * permission or disk error) logs at `warn`, since it is an accepted,\n   * expected occasional occurrence; anything else logs at `error`, since it\n   * is a defect in this Runtime's own capture logic and must stay visible\n   * rather than disappearing without trace. The README's Known Limitations\n   * names the residual case this still cannot recover from: capture itself\n   * has no automatic retry, so a logged failure means that run's eligible\n   * files stay uncaptured until the next run.\n   * @param session - exact live Session that owns the just-finished run.\n   * @param projectId - the session's already-resolved owning project.\n   * @param runScratch - the run's private Host scratch, including its artifact directory.\n   * @param terminal - the exact terminal record just committed, supplying every captured version's provenance.\n   * @param editBaselines - Validated exact parents keyed by capture-relative path.\n   * @param rasterArtifacts - Validated capture-relative `.png` paths this run declared for capture.\n   * @param charts - Validated chart state keyed by capture-relative PNG path.\n   * @returns Capture accounting and a safe failure classification independent of interpreter status.\n   */\n  private async captureAfterFinish(\n    session: StartScienceRunRequest['session'],\n    projectId: ScienceProjectId,\n    runScratch: Awaited<ReturnType<typeof createRunScratch>>,\n    terminal: ScienceRunTerminal,\n    editBaselines: PreparedRunArtifacts['editBaselines'],\n    rasterArtifacts: PreparedRunArtifacts['rasterArtifacts'],\n    charts: ReadonlyMap<string, ScienceChartState>,\n  ): Promise<Pick<ScienceRunResult, 'capture' | 'captureFailure'>> {\n    // The caller already re-verified liveness immediately before the\n    // run-finished append this method follows; only a detach racing that\n    // exact synchronous continuation reaches this, not deterministically\n    // reproducible in a test.\n    /* v8 ignore next */\n    if (this.ctx.sessions.get(session.id) !== session) return { captureFailure: 'session-detached' }\n    let result: CaptureRunArtifactsResult\n    try {\n      result = await captureRunArtifacts({\n        store: this.ctx.scienceArtifactStore,\n        projectId,\n        session,\n        runArtifacts: runScratch.artifacts,\n        sourceRun: terminal,\n        editBaselines,\n        rasterCapture: this.rasterCapture,\n        rasterArtifacts,\n        charts,\n        captureMaxFileBytes: this.captureMaxFileBytes,\n        captureMaxFilesPerRun: this.captureMaxFilesPerRun,\n        captureMaxArtifactVersionsPerSession: this.captureMaxArtifactVersionsPerSession,\n      })\n    } catch (error) {\n      const message = `science-runtime: auto-capture failed for session \"${session.id}\" run \"${terminal.runId}\": ${String(error)}`\n      if (isCaptureFilesystemFailure(error)) this.ctx.logger.warn(message)\n      else this.ctx.logger.error(message)\n      return { captureFailure: error instanceof ProjectArtifactStoreError && error.code === 'LOGICAL_NAME_INVALID'\n        ? 'invalid-logical-name'\n        : isCaptureFilesystemFailure(error) ? 'filesystem' : 'capture-failed' }\n    }\n    if (result.appendFailed) {\n      this.ctx.logger.warn(`science-runtime: auto-capture stopped early for session \"${session.id}\" run \"${terminal.runId}\": a session.append rejection interrupted the walk`)\n    }\n    return { capture: result, ...result.appendFailed ? { captureFailure: 'event-append-failed' as const } : {} }\n  }\n}\n\nexport default ScienceRuntime\n"
    },
    {
      "path": "packages/science/science-runtime/src/execution.ts",
      "content": "/** Kernel-run construction, confinement, bounded output reading, and terminal classification. */\n\nimport { randomUUID } from 'node:crypto'\nimport { Buffer } from 'node:buffer'\nimport { open, stat } from 'node:fs/promises'\nimport { join, win32 as pathWin32 } from 'node:path'\nimport { SandboxUnavailableError, writableRoots } from '@deepseek-ai/dsh-sandbox'\nimport type { ConfinedArgv, SandboxEnforcement, SandboxPolicy, SandboxProvider } from '@deepseek-ai/dsh-sandbox'\nimport { ScienceRunId, ScienceScratchKey } from '@deepseek-ai/dsh-science-session'\nimport type {\n  ScienceEnvironmentBinding,\n  ScienceInterpreterAvailableBinding,\n  ScienceLanguage,\n  ScienceRunArtifactInput,\n  ScienceRunStarted,\n  ScienceRunTerminal,\n} from '@deepseek-ai/dsh-science-session'\nimport type { Session } from '@deepseek-ai/dsh-session'\nimport type { SubprocessHandle } from '@deepseek-ai/dsh-subprocess'\nimport { pathsOverlap, sha256 } from './scratch.ts'\nimport type { ScienceRunScratch, ScienceSessionScratch } from './scratch.ts'\nimport { ScienceRuntimeError } from './types.ts'\nimport type { ScienceRunOutput } from './types.ts'\n\n/** Fixed maximum exact source bytes. */\nexport const MAX_SOURCE_BYTES = 262_144\n/** Fixed retained bytes per execution output stream. */\nexport const MAX_OUTPUT_BYTES = 64_000\n/** Fixed descendant grace before Runtime asks the subprocess seam to terminate. */\nexport const DESCENDANT_GRACE_MS = 3_000\nconst POSIX_LOCALE = 'C.UTF-8'\n/**\n * `en_US.UTF-8`, not the POSIX `C.UTF-8` every other non-Darwin platform\n * uses: a win32 R build (conda-forge's ucrt R 4.5.3) reads `LC_ALL`, and\n * under `C` its `l10n_info()$\"UTF-8\"` reports `FALSE` with an active code\n * page of 0 — every non-ASCII byte a spawned R process writes comes back as\n * `<U+XXXX>` escapes instead of UTF-8. Under `en_US.UTF-8` R sets the active\n * code page to 65001 (UTF-8) and starts with no locale warning. `C.UTF-8`\n * itself is not an option on win32: the platform's `setlocale` rejects it,\n * so R falls back to the same broken `C` behavior anyway. Confirmed on a\n * real Windows box; see the\n * [win32 locale and probe-argv\n * limitations](../README.md#known-limitations-and-deferred-work).\n */\nconst CHILD_LOCALES: Record<NodeJS.Platform, string> = {\n  aix: POSIX_LOCALE, android: POSIX_LOCALE, darwin: 'en_US.UTF-8', freebsd: POSIX_LOCALE, haiku: POSIX_LOCALE,\n  linux: POSIX_LOCALE, netbsd: POSIX_LOCALE, openbsd: POSIX_LOCALE, sunos: POSIX_LOCALE, win32: 'en_US.UTF-8', cygwin: POSIX_LOCALE,\n}\n/** Fixed trailing system directories appended after a POSIX prefix's own `bin`. */\nconst POSIX_PATH_SUFFIX = ':/usr/bin:/bin'\n/**\n * Fixed ordered Conda prefix subdirectories a win32 `PATH` needs, mirroring\n * what `conda activate` itself prepends on Windows: the prefix root first\n * (`python.exe` lives there, not under a `bin`), then the MSYS2/MinGW-toolchain\n * and Unix-utility shims under `Library`, then the prefix's own `Scripts`\n * and `bin`. Declared as win32 path segments (backslash-joined via\n * `path.win32`) regardless of the host platform this function runs on, since\n * the value is a literal `PATH` string for a spawned win32 child, never a\n * filesystem path this process itself resolves.\n */\nconst WINDOWS_PATH_SUBDIRECTORIES = ['', 'Library\\\\mingw-w64\\\\bin', 'Library\\\\usr\\\\bin', 'Library\\\\bin', 'Scripts', 'bin'] as const\n\n/** Win32 `PATH` value for a Conda prefix: see {@link WINDOWS_PATH_SUBDIRECTORIES}. */\nfunction windowsInterpreterPathEnv(canonicalPrefix: string): string {\n  return WINDOWS_PATH_SUBDIRECTORIES\n    .map(subdirectory => (subdirectory === '' ? canonicalPrefix : pathWin32.join(canonicalPrefix, subdirectory)))\n    .join(';')\n}\n\n/** Windows system variables required by interpreter startup and runtime libraries. */\nconst WIN32_AMBIENT_ENVIRONMENT_KEYS = [\n  'SystemRoot', 'windir', 'SystemDrive', 'ComSpec', 'PATHEXT',\n  'USERPROFILE', 'APPDATA', 'LOCALAPPDATA', 'PROGRAMDATA',\n  'NUMBER_OF_PROCESSORS', 'PROCESSOR_ARCHITECTURE',\n] as const\n\n/**\n * Fixed Windows system entries needed by empty-base interpreter processes.\n * Copies only the declared ambient keys and confines temporary files to scratch.\n * @param temporaryDirectory - the child operation's owned scratch temp directory.\n * @returns Windows ambient entries and TEMP/TMP, or no entries on other platforms.\n */\nexport function windowsEnvironment(temporaryDirectory: string): NodeJS.ProcessEnv {\n  if (process.platform !== 'win32') return {}\n  const entries: [string, string][] = []\n  for (const key of WIN32_AMBIENT_ENVIRONMENT_KEYS) {\n    const value = process.env[key]\n    if (value !== undefined) entries.push([key, value])\n  }\n  return { ...Object.fromEntries(entries), TEMP: temporaryDirectory, TMP: temporaryDirectory }\n}\n\n/** Complete pre-publication plan with no Host scratch path exposed publicly. */\nexport interface RunPlan {\n  readonly runId: ReturnType<typeof ScienceRunId>\n  readonly sourceBytes: Buffer\n  readonly scratchKey: ReturnType<typeof ScienceScratchKey>\n  readonly binding: ScienceInterpreterAvailableBinding\n}\n\n/**\n * Exact fixed locale values for a supported POSIX child. Shared by every\n * confined interpreter spawn: persistent kernels and interpreter probes alike.\n * @returns fixed `LANG`/`LC_ALL`/`TZ` entries for this host platform.\n */\nexport function localeEnvironment(): Pick<NodeJS.ProcessEnv, 'LANG' | 'LC_ALL' | 'TZ'> {\n  const locale = CHILD_LOCALES[process.platform]\n  return {\n    LANG: locale,\n    LC_ALL: locale,\n    TZ: 'UTC',\n  }\n}\n\n/**\n * Fixed `PATH` entry for a configured interpreter prefix: its own `bin`\n * ahead of the platform's ordinary system directories on POSIX, or the full\n * ordered Conda subdirectory list `conda activate` itself would set on win32\n * ({@link windowsInterpreterPathEnv}). Shared by every confined interpreter spawn.\n * @param canonicalPrefix - the observed binding's canonicalized Conda prefix.\n * @returns the exact `PATH` value for that prefix on this host platform.\n */\nexport function interpreterPathEnv(canonicalPrefix: string): string {\n  if (process.platform === 'win32') return windowsInterpreterPathEnv(canonicalPrefix)\n  return `${join(canonicalPrefix, 'bin')}${POSIX_PATH_SUFFIX}`\n}\n\n/**\n * Direct argv for one persistent kernel's interpreter invocation: fixed\n * per-language hardening flags followed by the caller's trailing script\n * arguments — the driver script path plus its response-channel endpoint\n * argument (an absolute FIFO path, or a `tcp:127.0.0.1:<port>:<token>` address on win32).\n * Never a shell command. Kernel-only: an interpreter probe builds its own\n * direct argv (`probeArgv` in `environment.ts`) and keeps Python `-I`\n * (isolated mode), since a probe never needs a writable package-install\n * target. A kernel drops `-I` so pip's user-site fallback under\n * `PYTHONUSERBASE` (`kernel-process.ts`'s `kernelEnvironment`) lands on\n * `sys.path` — the mechanism that makes an inline `pip install` importable\n * within the same kernel (see the README's \"Confinement and environment\").\n * @param language - selects the fixed flag set.\n * @param executable - canonical interpreter executable.\n * @param scriptArgs - trailing arguments appended after the fixed flags.\n * @returns the complete direct argv, unconfined.\n */\nexport function interpreterArgv(language: ScienceLanguage, executable: string, ...scriptArgs: readonly string[]): string[] {\n  return language === 'python'\n    ? [executable, '-B', '-u', '-X', 'utf8', ...scriptArgs]\n    : [executable, '--vanilla', '--encoding=UTF-8', ...scriptArgs]\n}\n\n/** Reject malformed/oversized source without adding or normalizing bytes. */\nfunction sourceBytes(code: string): Buffer {\n  if (code.length === 0 || code.includes('\\0') || !code.isWellFormed()) {\n    throw new ScienceRuntimeError('INVALID_REQUEST', 'Science source must be non-empty, well-formed Unicode without U+0000')\n  }\n  const bytes = Buffer.from(code, 'utf8')\n  if (bytes.byteLength > MAX_SOURCE_BYTES) {\n    throw new ScienceRuntimeError('INVALID_REQUEST', `Science source exceeds ${String(MAX_SOURCE_BYTES)} UTF-8 bytes`)\n  }\n  return bytes\n}\n\n/**\n * Select the durable available binding for a requested language. Shared by\n * run planning ({@link planRun}) and persistent kernel spawn\n * (`KernelSet.acquire` in `kernel-set.ts`).\n * @param environment - applied durable environment revision to select from.\n * @param language - requested interpreter language.\n * @returns the selected language's fully observed, available binding.\n * @throws {@link ScienceRuntimeError} (`ENVIRONMENT_NOT_READY`) when the\n *   revision is not `applied` or the requested language has no available binding.\n */\nexport function selectBinding(environment: ScienceEnvironmentBinding, language: ScienceLanguage): ScienceInterpreterAvailableBinding {\n  const binding = language === 'python' ? environment.python : environment.r\n  if (environment.status !== 'applied' || binding?.capability !== 'available') {\n    throw new ScienceRuntimeError('ENVIRONMENT_NOT_READY', `Science ${language} environment is not available`)\n  }\n  return binding\n}\n\n/**\n * Build pre-publication source and direct argv facts.\n * @param environment - Applied durable environment whose selected binding is required.\n * @param language - Requested interpreter language.\n * @param code - Exact caller source before UTF-8 validation and hashing.\n * @returns Private immutable facts needed to create and start one run.\n */\nexport function planRun(\n  environment: ScienceEnvironmentBinding,\n  language: ScienceLanguage,\n  code: string,\n): RunPlan {\n  const bytes = sourceBytes(code)\n  const binding = selectBinding(environment, language)\n  const runId = ScienceRunId(randomUUID())\n  const scratchKey = ScienceScratchKey(sha256(Buffer.concat([\n    Buffer.from(`dsh-science-scratch-v1\\0${language}\\0`, 'utf8'),\n    bytes,\n  ])))\n  return {\n    runId,\n    sourceBytes: bytes,\n    scratchKey,\n    binding,\n  }\n}\n\n/**\n * Fixed confinement policy rooted at exactly one canonical Science Session\n * scratch tree. Used for every persistent kernel spawn under that Session\n * (an interpreter probe's own policy is narrower, rooted at its probe\n * directory instead — see `environment.ts`).\n * @param session - exact live Session that owns the scratch tree.\n * @param scratch - that Session's private scratch paths.\n * @returns the fixed `workspace-write` sandbox policy.\n */\nexport function confinementPolicy(session: Session, scratch: ScienceSessionScratch): SandboxPolicy {\n  return { mode: 'workspace-write', workspaceRoot: scratch.root, sessionId: session.id }\n}\n\n/**\n * Reject every prefix that may be written through the selected sandbox policy.\n * @param prefix - the observed binding's canonicalized Conda prefix.\n * @param policy - the confinement policy the prefix must stay outside of.\n * @throws {@link ScienceRuntimeError} (`CONFINEMENT_UNAVAILABLE`) when the prefix overlaps a writable root.\n */\nexport function assertPrefixReadOnly(prefix: string, policy: SandboxPolicy): void {\n  for (const root of writableRoots(policy)) {\n    if (pathsOverlap(prefix, root)) {\n      throw new ScienceRuntimeError('CONFINEMENT_UNAVAILABLE', 'configured Conda prefix overlaps a sandbox writable root')\n    }\n  }\n}\n\n/**\n * Whether a confinement's reported enforcement satisfies a configured\n * minimum: `'full'` accepts only a `'full'` report; `'partial'` accepts\n * either `'full'` or `'partial'`. The sandbox provider itself never sees\n * this comparison — it always reports the level it actually achieved.\n * @param reported - enforcement level `SandboxProvider.confine` reported.\n * @param minimum - lowest level Science is configured to accept.\n * @returns whether `reported` meets or exceeds `minimum`.\n */\nexport function meetsMinimumEnforcement(reported: SandboxEnforcement, minimum: SandboxEnforcement): boolean {\n  return minimum === 'partial' || reported === 'full'\n}\n\n/**\n * Sandbox-confine one argv under an already-built policy: asserts the\n * interpreter's own prefix stays read-only and requires at least\n * `minimumEnforcement`. Shared by every Science confinement site —\n * persistent kernel spawn and interpreter probes alike — each of which\n * builds its own policy (a probe's differs from a kernel's: a narrower\n * `workspaceRoot`).\n * @param sandbox - sandbox provider performing the confinement.\n * @param canonicalPrefix - the observed binding's canonicalized Conda prefix.\n * @param policy - the caller's already-built confinement policy.\n * @param argv - direct, unconfined argv (see {@link interpreterArgv}).\n * @param minimumEnforcement - lowest enforcement level Science is configured\n *   to accept (`science-runtime`'s `minimumEnforcement` Config field).\n * @returns the confined argv and its denial/runner-failure classification evidence.\n * @throws {@link ScienceRuntimeError} (`CONFINEMENT_UNAVAILABLE`) when the\n *   sandbox is unavailable or reports less than `minimumEnforcement`; the\n *   message names both the reported and the required level.\n */\nexport function confineWithEnforcement(\n  sandbox: SandboxProvider,\n  canonicalPrefix: string,\n  policy: SandboxPolicy,\n  argv: readonly string[],\n  minimumEnforcement: SandboxEnforcement,\n): ConfinedArgv {\n  assertPrefixReadOnly(canonicalPrefix, policy)\n  return confineRequiringEnforcement(sandbox, policy, argv, minimumEnforcement)\n}\n\n/**\n * Confine a command and require the configured minimum enforcement.\n * @param sandbox - provider that confines the command.\n * @param policy - writable roots and session identity chosen by the caller.\n * @param argv - direct command arguments.\n * @param minimumEnforcement - lowest accepted enforcement level.\n * @returns confined arguments and execution classification evidence.\n * @throws {@link ScienceRuntimeError} (`CONFINEMENT_UNAVAILABLE`) when confinement is unavailable or insufficient.\n */\nexport function confineRequiringEnforcement(\n  sandbox: SandboxProvider,\n  policy: SandboxPolicy,\n  argv: readonly string[],\n  minimumEnforcement: SandboxEnforcement,\n): ConfinedArgv {\n  let confined: ConfinedArgv\n  try {\n    confined = sandbox.confine(argv, policy)\n  } catch (error) {\n    if (error instanceof SandboxUnavailableError) {\n      throw new ScienceRuntimeError('CONFINEMENT_UNAVAILABLE', 'Science requires an available sandbox', { cause: error })\n    }\n    throw error\n  }\n  if (!meetsMinimumEnforcement(confined.enforcement, minimumEnforcement)) {\n    throw new ScienceRuntimeError(\n      'CONFINEMENT_UNAVAILABLE',\n      `Science requires at least ${minimumEnforcement} sandbox enforcement; the sandbox reported ${confined.enforcement}`,\n    )\n  }\n  return confined\n}\n\n/**\n * Sandbox-confine one interpreter argv under a Session's `workspace-write`\n * policy: persistent kernel spawn confinement, rooted at the whole Session\n * scratch tree (unlike an interpreter probe's narrower policy).\n * @param session - exact live Session that owns the confinement policy.\n * @param scratch - that Session's private scratch paths.\n * @param sandbox - sandbox provider performing the confinement.\n * @param canonicalPrefix - the observed binding's canonicalized Conda prefix.\n * @param argv - direct, unconfined argv (see {@link interpreterArgv}).\n * @param minimumEnforcement - lowest enforcement level Science is configured\n *   to accept (`KernelProcessOptions.minimumEnforcement`, itself\n *   `science-runtime`'s configured `minimumEnforcement` forwarded through\n *   `KernelSetOptions`).\n * @returns the confined argv and its denial/runner-failure classification evidence.\n * @throws {@link ScienceRuntimeError} (`CONFINEMENT_UNAVAILABLE`) when the\n *   sandbox is unavailable or reports less than `minimumEnforcement`.\n */\nexport function confineInterpreterArgv(\n  session: Session,\n  scratch: ScienceSessionScratch,\n  sandbox: SandboxProvider,\n  canonicalPrefix: string,\n  argv: readonly string[],\n  minimumEnforcement: SandboxEnforcement,\n): ConfinedArgv {\n  return confineWithEnforcement(sandbox, canonicalPrefix, confinementPolicy(session, scratch), argv, minimumEnforcement)\n}\n\n/**\n * Run-terminal failure vocabulary for a kernel execution: `TIMEOUT`/\n * `CANCELLED` describe the operation's own abort cause; `EXECUTION_FAILED`\n * (the driver replied DONE `error`) and `KERNEL_DIED` (the kernel process\n * exited or broke protocol mid-run) describe the kernel protocol outcome. A\n * kernel run never populates a per-run exit code or signal.\n */\nexport type KernelRunFailureCode = 'TIMEOUT' | 'CANCELLED' | 'EXECUTION_FAILED' | 'KERNEL_DIED'\n\n/** Safe durable explanation for a kernel-run terminal classification. */\nfunction kernelFailureMessage(code: KernelRunFailureCode): string {\n  return {\n    TIMEOUT: 'The Science Runtime operation timed out.',\n    CANCELLED: 'The Science Runtime operation was cancelled.',\n    EXECUTION_FAILED: 'The interpreter raised an error while executing this run.',\n    KERNEL_DIED: 'The persistent kernel stopped unexpectedly during this run.',\n  }[code]\n}\n\n/**\n * Build one kernel-run terminal value from durable start fields and its terminal classification.\n * @param started - already committed durable run-start value, whole-value repeated.\n * @param stdout - bounded stdout tail read from this run's capture file.\n * @param stderr - bounded stderr tail read from this run's capture file.\n * @param status - the run's terminal status.\n * @param failureCode - present on every non-success status.\n * @param outputDegraded - whether the DONE frame carried the `capture-degraded` flag.\n * @returns the complete terminal value ready for one atomic Session append.\n */\nexport function kernelRunTerminal(\n  started: ScienceRunStarted,\n  stdout: ScienceRunOutput,\n  stderr: ScienceRunOutput,\n  status: ScienceRunTerminal['status'],\n  failureCode: KernelRunFailureCode | undefined,\n  outputDegraded: boolean,\n): ScienceRunTerminal {\n  return {\n    ...started,\n    status,\n    finishedAt: Date.now(),\n    stdoutBytes: stdout.bytes,\n    stderrBytes: stderr.bytes,\n    stdoutTruncated: stdout.truncated,\n    stderrTruncated: stderr.truncated,\n    ...(failureCode === undefined ? {} : { failureCode, failureMessage: kernelFailureMessage(failureCode) }),\n    ...(outputDegraded ? { outputDegraded: true as const } : {}),\n  }\n}\n\n/**\n * Read a bounded tail of one already-closed per-run capture file: the exact\n * byte count is the file's own size; `truncated` is whether that size\n * exceeds {@link MAX_OUTPUT_BYTES}; the retained `text` is the last\n * `MAX_OUTPUT_BYTES` bytes (\"retain tail\"), decoded UTF-8 without\n * multibyte-boundary alignment — matching the subprocess seam's own\n * in-memory tail collector, which truncates the same way. A missing file\n * (the driver never wrote to it — the run never reached user code) reads as\n * empty, not a failure.\n * @param path - absolute path of the per-run stdout or stderr capture file.\n * @returns the bounded output tail.\n */\nexport async function readCaptureTail(path: string): Promise<ScienceRunOutput> {\n  let size: number\n  try {\n    size = (await stat(path)).size\n  } catch {\n    return { text: '', bytes: 0, truncated: false }\n  }\n  if (size === 0) return { text: '', bytes: 0, truncated: false }\n  const truncated = size > MAX_OUTPUT_BYTES\n  const start = truncated ? size - MAX_OUTPUT_BYTES : 0\n  const handle = await open(path, 'r')\n  try {\n    const buffer = Buffer.alloc(size - start)\n    await handle.read(buffer, 0, buffer.length, start)\n    return { text: buffer.toString('utf8'), bytes: size, truncated }\n  } finally {\n    await handle.close()\n  }\n}\n\n/** Start an unbounded cleanup observation without allowing a synchronous throw to escape. */\nfunction awaitEventualQuiescence(handle: SubprocessHandle): Promise<boolean> {\n  return Promise.resolve().then(() => handle.waitForExit())\n}\n\n/** Wait briefly for a post-parent descendant tree, then use the one subprocess termination verb. */\nexport type Quiescence =\n  | { readonly quiescent: true; readonly forced: boolean }\n  | { readonly quiescent: false; readonly forced: true; readonly eventualQuiescence: Promise<boolean> }\n\n/**\n * Wait briefly for a subprocess tree to exit on its own, then escalate\n * through the seam's one termination verb and wait again. Used by\n * persistent kernel teardown, both ordinary (`KernelProcess.end`) and\n * spawn-failure cleanup.\n * @param handle - the live subprocess handle to quiesce.\n * @returns whether the tree proved quiescent, whether termination was\n *   forced, and (when still unproven) the retained eventual-quiescence observation.\n */\nexport async function quiesce(handle: SubprocessHandle): Promise<Quiescence> {\n  try {\n    const grace = AbortSignal.timeout(DESCENDANT_GRACE_MS)\n    if (await handle.waitForExit(grace)) return { quiescent: true, forced: false }\n  } catch {\n    // A provider that cannot answer the bounded observation has not proven the tree dead.\n  }\n  try {\n    handle.terminate()\n  } catch {\n    return { quiescent: false, forced: true, eventualQuiescence: awaitEventualQuiescence(handle) }\n  }\n  try {\n    const forced = AbortSignal.timeout(DESCENDANT_GRACE_MS)\n    if (await handle.waitForExit(forced)) return { quiescent: true, forced: true }\n  } catch {\n    // Keep the exact-Session quarantine until the provider can later prove exit.\n  }\n  return { quiescent: false, forced: true, eventualQuiescence: awaitEventualQuiescence(handle) }\n}\n\n/**\n * Create a start candidate after source was flushed but before the RUN frame is sent.\n * @param plan - Private immutable run plan.\n * @param run - Flushed private run directory facts.\n * @param language - Requested interpreter language.\n * @param environment - Applied durable environment revision.\n * @param toolCallId - Still-pending authorization call that owns the run.\n * @param requestHeaderSeq - Durable request-header sequence that owns provenance.\n * @param kernelEpoch - session-local epoch of the kernel that will execute this run (already acquired).\n * @param inputs - Exact artifact-version inputs materialized for this run.\n * @returns Durable start fields ready for one atomic Session append.\n */\nexport function startCandidate(\n  plan: RunPlan,\n  run: ScienceRunScratch,\n  language: ScienceLanguage,\n  environment: ScienceEnvironmentBinding,\n  toolCallId: ScienceRunStarted['toolCallId'],\n  requestHeaderSeq: number,\n  kernelEpoch: number,\n  inputs: readonly ScienceRunArtifactInput[],\n): ScienceRunStarted {\n  return {\n    runId: plan.runId,\n    language,\n    toolCallId,\n    requestHeaderSeq,\n    environmentRevision: environment.revision,\n    environmentFingerprint: plan.binding.bindingFingerprint,\n    startedAt: Date.now(),\n    codeSha256: sha256(plan.sourceBytes),\n    scratchKey: plan.scratchKey,\n    runDirectoryRef: run.ref,\n    ...(inputs.length === 0 ? {} : { inputs }),\n    kernelEpoch,\n    status: 'running',\n  }\n}\n"
    },
    {
      "path": "packages/science/science-runtime/src/capture.ts",
      "content": "/**\n * Auto-capture: walk one terminal run's artifact directory and durably save\n * every eligible file as a versioned Science artifact — bytes into the owning\n * project's artifact store, then one `science/artifact-saved` store-reference\n * event — with no model involvement. Hooked from\n * `ScienceRuntime.settlePublishedRun` (index.ts) immediately after each of\n * its two `science/run-finished` append sites.\n */\n\nimport { isScienceLogicalName } from '@deepseek-ai/dsh-science-artifact-store/logical-name'\nimport { createHash } from 'node:crypto'\nimport { lstat } from 'node:fs/promises'\nimport { basename, extname, join } from 'node:path'\nimport { ProjectArtifactStoreError } from '@deepseek-ai/dsh-science-artifact-store'\nimport type { ArtifactKind, ScienceArtifactStore, VersionRecord } from '@deepseek-ai/dsh-science-artifact-store'\nimport { applyScienceEvent, foldScience, projectScienceFold } from '@deepseek-ai/dsh-science-session'\nimport type {\n  ScienceArtifactMediaType,\n  ScienceArtifactVersion,\n  ScienceArtifactVersionRef,\n  ScienceChartState,\n  ScienceFoldState,\n  ScienceProjectId,\n  ScienceRunTerminal,\n  ScienceVersionId,\n} from '@deepseek-ai/dsh-science-session'\nimport type { Session } from '@deepseek-ai/dsh-session'\nimport { canonicalWithin } from './scratch.ts'\nimport { readBoundedFile, walkArtifactFiles } from './artifact-file.ts'\n\n/**\n * Fixed auto-capture extension allowlist, keyed by lower-cased extension.\n * Product scope, not a Loader-exposed knob: no current deployment needs a\n * narrower or wider captured-file type set.\n */\nconst CAPTURE_MEDIA_TYPE_BY_EXTENSION: ReadonlyMap<string, ScienceArtifactMediaType> = new Map([\n  ['.png', 'image/png'],\n  ['.csv', 'text/csv'],\n  ['.json', 'application/json'],\n  ['.md', 'text/markdown'],\n  ['.txt', 'text/plain'],\n])\n\n/** Resolve a capture media type from the path's final suffix. */\nfunction captureMediaType(relativePath: string): ScienceArtifactMediaType | undefined {\n  const lower = relativePath.toLowerCase()\n  return CAPTURE_MEDIA_TYPE_BY_EXTENSION.get(extname(lower))\n}\n\n/** Whether a walked relative path is eligible for auto-capture: no dotfile/dot-directory segment, and an allowlisted extension. */\nfunction isCaptureEligible(relativePath: string): boolean {\n  if (relativePath.split('/').some(segment => segment.startsWith('.'))) return false\n  return captureMediaType(relativePath) !== undefined\n}\n\n/**\n * Validated `rasterCapture` Config policy for one run's auto-capture walk.\n * `'declared'` (the default) captures a `.png` only when the run request\n * named it in `rasterArtifacts`; a self-inspection render the model writes\n * for its own QA never becomes a redundant artifact. `'always'`\n * captures every eligible `.png` unconditionally, matching the auto-capture\n * walk's pre-existing behavior for every other accepted extension.\n */\nexport type RasterCapturePolicy = 'declared' | 'always'\n\n/** Whether one eligible PNG path may be captured under the run's raster-capture policy. */\nfunction isRasterCaptureAllowed(\n  relativePath: string,\n  mediaType: ScienceArtifactMediaType,\n  rasterCapture: RasterCapturePolicy,\n  rasterArtifacts: ReadonlySet<string>,\n): boolean {\n  return mediaType !== 'image/png' || rasterCapture === 'always' || rasterArtifacts.has(relativePath)\n}\n\n/**\n * List existing PNG paths admitted by the same rules as auto-capture.\n * @param runArtifacts - canonical run artifact directory.\n * @param rasterCapture - configured PNG capture policy.\n * @param rasterArtifacts - validated declared PNG paths.\n * @returns sorted capture-relative PNG paths eligible for capture.\n */\nexport async function capturablePngPaths(\n  runArtifacts: string,\n  rasterCapture: RasterCapturePolicy,\n  rasterArtifacts: ReadonlySet<string>,\n): Promise<readonly string[]> {\n  const walked = (await walkArtifactFiles(runArtifacts)).filter(isCaptureEligible).sort()\n  return walked.filter((relativePath) => {\n    const mediaType = captureMediaType(relativePath)\n    return mediaType === 'image/png'\n      && isRasterCaptureAllowed(relativePath, mediaType, rasterCapture, rasterArtifacts)\n  })\n}\n\n/** Inputs for one terminal run's auto-capture walk. */\nexport interface CaptureRunArtifactsRequest {\n  /** Project artifact store that owns every captured version's bytes and index row. */\n  readonly store: ScienceArtifactStore\n  /** The session's already-resolved owning project. */\n  readonly projectId: ScienceProjectId\n  /** Exact live Session that owns the captured versions' events. */\n  readonly session: Session\n  /** The source run's canonical, already-verified artifact directory. */\n  readonly runArtifacts: string\n  /** The exact terminal run whose artifact directory is walked; supplies every version's provenance fields. */\n  readonly sourceRun: ScienceRunTerminal\n  /** Validated exact parent refs keyed by capture-relative output path. */\n  readonly editBaselines?: ReadonlyMap<string, ScienceArtifactVersionRef>\n  /** Validated Runtime config: this run's raster-capture policy. */\n  readonly rasterCapture: RasterCapturePolicy\n  /** Validated capture-relative `.png` paths this run declared for capture; consulted only under the `'declared'` policy. */\n  readonly rasterArtifacts: ReadonlySet<string>\n  /** Validated chart state keyed by capture-relative PNG path. */\n  readonly charts?: ReadonlyMap<string, ScienceChartState>\n  /** Validated Runtime config bound on one captured file's encoded bytes. */\n  readonly captureMaxFileBytes: number\n  /** Validated Runtime config bound on eligible files captured from one run. */\n  readonly captureMaxFilesPerRun: number\n  /** Validated Runtime config bound on artifact versions a session accumulates through auto-capture. */\n  readonly captureMaxArtifactVersionsPerSession: number\n}\n\n/** Outcome of one auto-capture walk: every version it appended, plus non-silent accounting for what it skipped. */\nexport interface CaptureRunArtifactsResult {\n  /** Versions this walk appended, in capture order. */\n  readonly captured: readonly ScienceArtifactVersion[]\n  /**\n   * Otherwise-eligible `.png` paths left uncaptured under the `'declared'`\n   * raster-capture policy because this run did not name them in\n   * `rasterArtifacts`. Always empty under `'always'`.\n   */\n  readonly skippedRasterPaths: readonly string[]\n  /** Eligible files skipped for exceeding `captureMaxFileBytes`. */\n  readonly skippedOversizedCount: number\n  /** Whether more eligible files existed than `captureMaxFilesPerRun` admits; the excess were not attempted. */\n  readonly truncatedPerRun: boolean\n  /** Whether `captureMaxArtifactVersionsPerSession` was reached before every eligible file was attempted. */\n  readonly truncatedPerSession: boolean\n  /**\n   * Whether a `session.append` rejection (the Session detached, or\n   * otherwise refused the append) stopped the walk before every eligible\n   * file was attempted.\n   */\n  readonly appendFailed: boolean\n  /** Captured PNG paths that had no valid extracted chart state. */\n  readonly chartUnavailablePaths: readonly string[]\n}\n\n/**\n * Resolve one capture media type to the store's artifact-kind vocabulary,\n * for a brand-new artifact's `createArtifact` call. Exhaustive over\n * {@link ScienceArtifactMediaType}'s closed set, mirroring the same mapping\n * the store's own v1→v2 migration uses to infer `kind` from legacy data\n * (`schema.ts`'s `inferArtifactKind`).\n */\nfunction artifactKindForMediaType(mediaType: ScienceArtifactMediaType): ArtifactKind {\n  switch (mediaType) {\n    case 'image/png': return 'figure'\n    case 'text/csv': return 'dataset'\n    case 'application/json':\n    case 'text/markdown':\n    case 'text/plain':\n      return 'document'\n    /* v8 ignore next 2 -- ScienceArtifactMediaType is closed and every member is handled above. */\n    default:\n      return assertNeverCaptureMediaType(mediaType)\n  }\n}\n\n/* v8 ignore next 3 -- see assertNeverCaptureMediaType's only caller, above. */\nfunction assertNeverCaptureMediaType(mediaType: never): never {\n  throw new Error(`science-runtime: unreachable ScienceArtifactMediaType ${JSON.stringify(mediaType)}`)\n}\n\n/**\n * Walk `request.runArtifacts`, admitting every eligible file into the owning\n * project's artifact store as the next version of the logical artifact named\n * by its path relative to that directory, then committing the matching\n * store-reference `science/artifact-saved` event. Content addressing makes\n * admission idempotent: an unchanged file's checksum equals the store's\n * current head version for that logical name, so this walk skips it rather\n * than appending a redundant version. After a direct human edit, a file that\n * still matches the latest run-produced ancestor is also skipped unless this\n * run explicitly names that path in `editBaselines`; this prevents an untouched\n * stale workspace file from reverting the human edit while preserving an\n * intentional model edit or revert — both facts (the head's `sha256` and its\n * `contentOrigin`) are read from the store, the sole authority for a\n * version's provenance, rather than from this session's own local history,\n * which is also what lets a logical name another session already created in\n * this project continue here instead of colliding with the store's\n * `UNIQUE(owningProjectId, logicalName)` constraint. Never throws for an\n * oversized file, a per-run/per-session cap, or a Session that detaches\n * mid-walk — each stops capture early (accounted in the returned result)\n * rather than failing the run that already committed its terminal fact. A\n * store write whose event append is then vetoed is marked `orphan` on the\n * store's own `version_health` row immediately, rather than waiting for a\n * later reconciliation pass.\n * @param request - the source run, its artifact directory, store coordinates, and validated Config bounds.\n * @returns every version appended, plus accounting for what the walk skipped.\n */\nexport async function captureRunArtifacts(request: CaptureRunArtifactsRequest): Promise<CaptureRunArtifactsResult> {\n  const { session, sourceRun, store, projectId } = request\n  const walked = (await walkArtifactFiles(request.runArtifacts)).filter(isCaptureEligible).sort()\n  const skippedRasterPaths = walked.filter((relativePath) => {\n    const mediaType = captureMediaType(relativePath)\n    /* v8 ignore next -- isCaptureEligible already required a mapped extension */\n    if (mediaType === undefined) return false\n    return !isRasterCaptureAllowed(relativePath, mediaType, request.rasterCapture, request.rasterArtifacts)\n  })\n  const eligible = walked.filter(relativePath => !skippedRasterPaths.includes(relativePath))\n  if (eligible.some(relativePath => !isScienceLogicalName(relativePath))) {\n    throw new ProjectArtifactStoreError('Science capture contains an invalid logical name', 'LOGICAL_NAME_INVALID')\n  }\n  const truncatedPerRun = eligible.length > request.captureMaxFilesPerRun\n  const files = eligible.slice(0, request.captureMaxFilesPerRun)\n\n  const captured: ScienceArtifactVersion[] = []\n  const chartUnavailablePaths: string[] = []\n  let skippedOversizedCount = 0\n  let truncatedPerSession = false\n  let appendFailed = false\n  // Advance from the complete log incrementally, including events appended\n  // by kernel teardown while the artifact store performs asynchronous I/O.\n  const state: ScienceFoldState = foldScience(session.snapshotEvents())\n  // The authorizing run's own turn number, read once from this same fold's\n  // tool-call index (`tool/call` facts are unaffected by the Science\n  // artifact-event slimming) rather than per file — the authorizing call is\n  // fixed for the whole walk.\n  const authorizingCall = state.toolCalls.find(call => call.callId === sourceRun.toolCallId)\n  /* v8 ignore next 3 -- run-started already validated this toolCallId against a recorded tool/call event in this session */\n  if (authorizingCall === undefined) {\n    throw new Error('science-runtime: capture could not locate the authorizing run\\'s tool/call event')\n  }\n  const producerTurn = authorizingCall.turn\n\n  // D7: lazily list every artifact this project's store already knows,\n  // once per walk, so a logical name this SESSION has never captured before\n  // can still continue an artifact a DIFFERENT session already created in\n  // the same project, instead of colliding with `createArtifact`'s\n  // `UNIQUE(owningProjectId, logicalName)` constraint.\n  let projectArtifactIdsByName: ReadonlyMap<string, ScienceArtifactVersion['artifactId']> | undefined\n  const projectArtifactIdFor = async (logicalName: string): Promise<ScienceArtifactVersion['artifactId'] | undefined> => {\n    if (projectArtifactIdsByName === undefined) {\n      const known = await store.listArtifacts(projectId)\n      projectArtifactIdsByName = new Map(known.map(candidate => [candidate.logicalName, candidate.artifactId]))\n    }\n    return projectArtifactIdsByName.get(logicalName)\n  }\n\n  for (const relativePath of files) {\n    const mediaType = captureMediaType(relativePath)\n    /* v8 ignore next -- isCaptureEligible already required a mapped extension */\n    if (mediaType === undefined) continue\n\n    const projection = projectScienceFold(state)\n    /* v8 ignore next -- capture only ever runs after a durable science/run-finished commit, which requires a bound Science mode */\n    if (projection === null) break\n    if (projection.artifacts.length >= request.captureMaxArtifactVersionsPerSession) {\n      truncatedPerSession = true\n      break\n    }\n\n    let canonical: string\n    try {\n      canonical = await canonicalWithin(request.runArtifacts, join(request.runArtifacts, ...relativePath.split('/')))\n    } catch {\n      // The walk observed this entry, but it no longer resolves under the\n      // run's artifact directory (removed, or replaced by a symlink,\n      // between the walk and this check) — skip it, not a run failure.\n      /* v8 ignore next -- a TOCTOU race, not deterministically reproducible; mirrors the accepted crash-between-commit-and-capture gap */\n      continue\n    }\n    const entry = await lstat(canonical)\n    // Re-verify kind defensively: walkArtifactFiles already required a\n    // regular non-symlink entry, so only a TOCTOU race changes that before\n    // this re-check (same non-reproducible race as the branch above).\n    /* v8 ignore next */\n    if (!entry.isFile() || entry.isSymbolicLink()) continue\n    // A bounded read never pulls more than captureMaxFileBytes + 1 bytes\n    // into memory, so an oversized file is caught by its returned length\n    // rather than a separate stat-based pre-check (artifact-file.ts).\n    const data = await readBoundedFile(canonical, request.captureMaxFileBytes)\n    if (data.byteLength > request.captureMaxFileBytes) {\n      skippedOversizedCount += 1\n      continue\n    }\n    const sha256 = createHash('sha256').update(data).digest('hex')\n\n    const localKnown = projection.artifacts.filter(candidate => candidate.logicalName === relativePath)\n    const localLatest = localKnown.at(-1)\n    let artifactId = localLatest?.artifactId ?? await projectArtifactIdFor(relativePath)\n\n    if (artifactId !== undefined) {\n      // The store, not this session's own local history, is the sole\n      // authority for a version's content_origin and sha256 (T1's authority\n      // rule) — both the same-content skip and the human-edit stale-skip\n      // below read the store's current head and history rather than\n      // `localKnown`, which no longer carries either fact and would also\n      // miss a head another session advanced.\n      const head = await store.getLatestVersion(projectId, artifactId)\n      // An artifactId resolved here (from this session's own fold or D7's\n      // listArtifacts lookup) always names a real, already-committed store\n      // row, which always has a latest version.\n      /* v8 ignore next */\n      if (head !== undefined) {\n        if (head.sha256 === sha256) continue\n        if (head.contentOrigin === 'human-edit' && request.editBaselines?.has(relativePath) !== true) {\n          const history = await store.listVersions(projectId, artifactId)\n          const latestRunProduced = history.findLast(candidate => candidate.contentOrigin !== 'human-edit')\n          if (latestRunProduced?.sha256 === sha256) continue\n        }\n      }\n    }\n\n    const parent = request.editBaselines?.get(relativePath)\n    let parentVersionId: ScienceVersionId | undefined\n    if (parent !== undefined) {\n      const parentVersion = projection.artifacts.find(candidate =>\n        candidate.artifactId === parent.artifactId && candidate.version === parent.version)\n      /* v8 ignore next 3 -- prepareRunArtifacts validated every baseline against this same projection before the run started */\n      if (parentVersion === undefined) {\n        throw new Error('science-runtime: capture edit baseline no longer identifies a committed artifact version')\n      }\n      parentVersionId = parentVersion.versionId\n    }\n\n    const chart = mediaType === 'image/png' ? request.charts?.get(relativePath) : undefined\n    const figureState = chart === undefined\n      ? undefined\n      : { figureKey: chart.figureKey, dpi: chart.png.dpi, stateJson: JSON.stringify(chart) }\n    const provenance = {\n      producerRunId: String(sourceRun.runId),\n      producerToolCallId: String(sourceRun.toolCallId),\n      producerRequestHeaderSeq: sourceRun.requestHeaderSeq,\n      environmentRevision: sourceRun.environmentRevision,\n      environmentFingerprint: sourceRun.environmentFingerprint,\n      producerTurn,\n      ...parentVersionId === undefined ? {} : { baseVersionId: parentVersionId },\n      ...figureState === undefined ? {} : { figureState },\n    }\n\n    // The store row commits before its session event: the event carries the\n    // validated store coordinates as fact (S0's Host-side pre-commit rule).\n    let stored: VersionRecord\n    if (artifactId !== undefined) {\n      stored = await store.appendVersion(projectId, artifactId, { producerSessionId: session.id, data, mediaType, contentOrigin: 'run-auto', ...provenance })\n    } else {\n      try {\n        stored = (await store.createArtifact(projectId, {\n          logicalName: relativePath,\n          kind: artifactKindForMediaType(mediaType),\n          originSessionId: session.id,\n          data,\n          mediaType,\n          contentOrigin: 'run-auto',\n          ...provenance,\n        })).version\n      } catch (error) {\n        // A different session raced this same logical name into existence\n        // between this walk's D7 lookup and this create call — the store's\n        // own UNIQUE(owningProjectId, logicalName) constraint is the true\n        // serialization point; re-resolve and append onto the winner rather\n        // than failing this file.\n        if (!(error instanceof ProjectArtifactStoreError) || error.code !== 'LOGICAL_NAME_CONFLICT') throw error\n        const known = await store.listArtifacts(projectId)\n        const winner = known.find(candidate => candidate.logicalName === relativePath)\n        /* v8 ignore next 3 -- the conflict error itself proves a row with this logicalName now exists */\n        if (winner === undefined) throw error\n        artifactId = winner.artifactId\n        stored = await store.appendVersion(projectId, artifactId, { producerSessionId: session.id, data, mediaType, contentOrigin: 'run-auto', ...provenance })\n      }\n    }\n\n    const title = basename(relativePath)\n    await store.annotateVersion(projectId, stored.versionId, { actor: 'capture', sessionId: session.id, title })\n\n    const artifact: ScienceArtifactVersion = {\n      artifactId: stored.artifactId,\n      logicalName: relativePath,\n      // New content always opens the next version; the store's per-artifact\n      // ordinal is that version number, so the log and the index agree.\n      version: stored.ordinal,\n      title,\n      projectId,\n      versionId: stored.versionId,\n      sha256: stored.sha256,\n      seenAt: Date.now(),\n    }\n    let appended\n    try {\n      appended = session.append('science/artifact-saved', { version: 1, artifact })\n    } catch {\n      // The Session detached (or otherwise refused the append) between the\n      // walk starting and this file's commit: remaining eligible files in\n      // this run stay uncaptured with no automatic retry, and the store row\n      // just written is marked orphan immediately rather than left for a\n      // later reconciliation pass to discover. `appendFailed` on the\n      // returned result is this fact's only signal to the caller\n      // (`ScienceRuntime.captureAfterFinish`, which logs it).\n      appendFailed = true\n      try {\n        await store.setVersionHealth(projectId, stored.versionId, { orphan: true })\n      } catch {\n        // The append already failed for this file; a health-marking failure\n        // on top of it leaves the row for the next reconciliation pass\n        // instead of compounding this walk's error.\n      }\n      break\n    }\n    for (const event of session.snapshotEvents().slice(state.nextSeq, appended.seq + 1)) {\n      applyScienceEvent(state, event)\n    }\n    captured.push(artifact)\n    if (mediaType === 'image/png' && figureState === undefined) chartUnavailablePaths.push(relativePath)\n  }\n\n  return {\n    captured,\n    skippedRasterPaths,\n    skippedOversizedCount,\n    truncatedPerRun,\n    truncatedPerSession,\n    appendFailed,\n    chartUnavailablePaths,\n  }\n}\n"
