      "path": "packages/science/tool-science/src/run.ts",
      "content": "/** `run_python` and `run_r`: one fresh interpreter execution through `ctx.scienceRuntime`. */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { formatBytes } from '@deepseek-ai/dsh-byte-size'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { InferValue, ToolExecution } from '@deepseek-ai/dsh-tools'\nimport type {} from '@deepseek-ai/dsh-science-runtime'\nimport type { ScienceRunResult } from '@deepseek-ai/dsh-science-runtime/types'\nimport type ScienceArtifactStore from '@deepseek-ai/dsh-science-artifact-store'\nimport type { VersionRecord } from '@deepseek-ai/dsh-science-artifact-store'\nimport { decodeScienceChartState, replayScience, ScienceArtifactId } from '@deepseek-ai/dsh-science-session'\nimport type {\n  ScienceArtifactMediaType,\n  ScienceArtifactVersion,\n  ScienceLanguage,\n  ScienceProjection,\n  ScienceRunTerminal,\n} from '@deepseek-ai/dsh-science-session'\nimport type { Session } from '@deepseek-ai/dsh-session'\nimport { closedKernelFacts, isScienceSession, modelKernelEndReason } from './context.ts'\nimport { requireDirectDispatch } from './guard.ts'\nimport { scienceArtifactPresentation } from './presentation.ts'\nimport type { ScienceArtifactPresentationItem } from './presentation.ts'\nimport { formatScienceArtifactEdits, scienceArtifactEdits, scienceArtifactSchemaProperties, scienceArtifactValueFields } from './artifact-schema.ts'\nimport type { ResolveArtifactStoreFacts, ScienceArtifactLineage, ScienceArtifactStoreFacts } from './artifact-schema.ts'\n\nconst outputStreamSchema = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    text: { type: 'string', required: true },\n    bytes: { type: 'integer', required: true },\n    truncated: { type: 'boolean', required: true },\n  },\n} as const\n\nconst artifactVersionRefSchema = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    artifactId: { type: 'string', required: true },\n    version: { type: 'integer', required: true },\n  },\n} as const\n\nconst runArtifactRefSchema = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    ...artifactVersionRefSchema.properties,\n    path: { type: 'string', required: true },\n  },\n} as const\n\nconst capturedArtifactSchema = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    // `title` and the store version id are carried for `presentationMeta`\n    // (below) to build a clickable Client reference per file; `render()`\n    // deliberately omits both from the model-visible receipt text — `title`\n    // duplicates `logicalName` for every auto-captured file (see capture.ts's\n    // `basename` default), and versionId is an internal storage coordinate,\n    // not a fact the model reasons about — the same split\n    // `annotate_artifact`'s own receipt schema uses.\n    ...scienceArtifactSchemaProperties,\n    versionId: { type: 'string', required: true },\n    lineage: {\n      oneOf: [\n        {\n          type: 'object', additionalProperties: false,\n          properties: {\n            kind: { type: 'string', const: 'edited-from', required: true },\n            logicalName: { type: 'string', required: true },\n            version: { type: 'integer', required: true },\n          },\n        },\n        {\n          type: 'object', additionalProperties: false,\n          properties: {\n            kind: { type: 'string', const: 'continues', required: true },\n            version: { type: 'integer', required: true },\n          },\n        },\n      ],\n    },\n  },\n} as const\n\nconst runOutputSchema = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    status: { type: 'string', enum: ['success', 'failed', 'timed-out', 'cancelled'], required: true },\n    // Present only when this is the first run on a kernel epoch that\n    // followed an earlier one for this language — the one kernel fact the\n    // model needs told: a fresh interpreter replaced the\n    // one that held whatever state earlier runs left behind.\n    kernelRestartReason: { type: 'string' },\n    runId: { type: 'string', required: true },\n    startedAt: { type: 'integer', required: true },\n    finishedAt: { type: 'integer', required: true },\n    failureCode: { type: 'string' },\n    failureMessage: { type: 'string' },\n    stdout: { ...outputStreamSchema, required: true },\n    stderr: { ...outputStreamSchema, required: true },\n    // Absent entirely for a non-quiescent settlement's async capture walk,\n    // which has no synchronous result to attach to this call (see\n    // ScienceRunResult.capture's own docstring); present (possibly with an\n    // empty capturedArtifacts array) whenever capture ran synchronously.\n    capturedArtifacts: { type: 'array', items: capturedArtifactSchema },\n    captureSkippedOversizedCount: { type: 'integer' },\n    captureFailure: { type: 'string' },\n    captureTruncatedPerRun: { type: 'boolean' },\n    captureTruncatedPerSession: { type: 'boolean' },\n    // Undeclared `.png` paths this run wrote under SCIENCE_ARTIFACT_DIR but\n    // that the 'declared' raster-capture policy left uncaptured — empty\n    // under the 'always' policy, and absent (not an empty array) when\n    // capture did not run synchronously, matching capturedArtifacts' own split.\n    skippedRaster: { type: 'array', items: { type: 'string' } },\n  },\n} as const\n\n/** Bounded structured value for a durably committed run terminal state. */\nexport type ScienceRunValue = InferValue<typeof runOutputSchema>\n\n/**\n * Require the exact initiating Agent's live Session and its science-preset identity.\n * @param exec - tool execution identity carrying the optional initiating Agent.\n * @returns the initiating Agent's Session.\n */\nexport function requireScienceSession(exec: ToolExecution): Session {\n  const session = exec.agent?.session\n  if (session === undefined) throw new Error('tool-science: this tool requires an initiating Agent')\n  if (!isScienceSession(session)) throw new Error('tool-science: this tool requires a session bound to the science preset')\n  return session\n}\n\n/**\n * Find the latest `request/header` event required to authorize a direct Science mutation.\n * @param session - exact Session whose request history authorizes the mutation.\n * @returns the latest request-header sequence, or `undefined` when none exists.\n */\nexport function latestRequestHeaderSeq(session: Session): number | undefined {\n  return session.snapshotEvents().findLast(event => event.type === 'request/header')?.seq\n}\n\n/**\n * Read the optional `ctx.scienceArtifactStore` service, failing loud when no\n * project artifact store is mounted. A plain function-plugin `Context`'s\n * `ctx.<name>` property proxy is reserved for names this package's own\n * `inject` declares; `scienceArtifactStore` is not one of them (only\n * `dsh-science-runtime` requires it), so every tool that reads the store\n * directly resolves it through `ctx.get` instead.\n * @param ctx - plugin context.\n * @returns the mounted project artifact store service.\n */\nexport function requireArtifactStore(ctx: Context): ScienceArtifactStore {\n  const store = ctx.get('scienceArtifactStore')\n  if (store === undefined) throw new Error('tool-science: no Science Artifact Store is mounted (ctx.scienceArtifactStore)')\n  return store\n}\n\n/**\n * Resolve one session-visible artifact version's store-owned model facts.\n * @param ctx - plugin context.\n * @param directEditLimit - maximum recent direct-edit summaries to return.\n * @param artifact - the session-visible artifact version to resolve.\n * @returns the version row and bounded PNG edit history.\n * @throws when the store no longer holds a version by this exact reference — a\n *   durable invariant violation, since the store commit always precedes the\n *   session event that names it.\n */\nexport async function resolveArtifactStoreFacts(\n  ctx: Context,\n  directEditLimit: number,\n  artifact: ScienceArtifactVersion,\n): Promise<ScienceArtifactStoreFacts> {\n  const store = requireArtifactStore(ctx)\n  const version = await store.getVersion(artifact.projectId, artifact.versionId)\n  if (version === undefined) {\n    throw new Error('tool-science: artifact no longer identifies a committed store version')\n  }\n  const figureState = version.mediaType === 'image/png'\n    ? await store.getFigureState(artifact.projectId, artifact.versionId)\n    : undefined\n  const chart = figureState === undefined ? undefined : decodeScienceChartState(JSON.parse(figureState.stateJson))\n  return {\n    version,\n    ...scienceArtifactEdits(chart, directEditLimit),\n  }\n}\n\n/**\n * Resolve store facts plus the model-visible lineage used by a run capture receipt.\n * @param ctx - plugin context.\n * @param directEditLimit - maximum recent direct-edit summaries to return.\n * @param artifact - the captured artifact version to resolve.\n * @returns store facts with explicit-edit or ordinary-continuation lineage when applicable.\n */\nexport async function resolveCapturedArtifactStoreFacts(\n  ctx: Context,\n  directEditLimit: number,\n  artifact: ScienceArtifactVersion,\n): Promise<ScienceArtifactStoreFacts> {\n  const facts = await resolveArtifactStoreFacts(ctx, directEditLimit, artifact)\n  return {\n    ...facts,\n    ...await resolveArtifactLineage(requireArtifactStore(ctx), artifact, facts.version),\n  }\n}\n\nasync function resolveArtifactLineage(\n  store: ScienceArtifactStore,\n  artifact: ScienceArtifactVersion,\n  version: VersionRecord,\n): Promise<{ readonly lineage?: ScienceArtifactLineage }> {\n  if (version.baseVersionId === undefined) {\n    return version.ordinal > 1 ? { lineage: { kind: 'continues', version: version.ordinal - 1 } } : {}\n  }\n  const base = await store.getVersion(artifact.projectId, version.baseVersionId)\n  if (base === undefined) throw new Error('tool-science: artifact baseline no longer identifies a committed store version')\n  if (!version.baseExplicit) return { lineage: { kind: 'continues', version: base.ordinal } }\n  const baseArtifact = await store.getArtifact(artifact.projectId, base.artifactId)\n  if (baseArtifact === undefined) throw new Error('tool-science: artifact baseline no longer identifies a committed artifact')\n  return { lineage: { kind: 'edited-from', logicalName: baseArtifact.logicalName, version: base.ordinal } }\n}\n\n/** Reject empty or whitespace-only source before it reaches the Runtime. */\nfunction nonEmptyCode(code: string): string {\n  if (code.trim().length === 0) throw new Error('tool-science: code must be a non-empty string')\n  return code\n}\n\n/**\n * Flatten one captured artifact version into the run result's bounded\n * listing entry.\n * @param artifact - the session-visible captured artifact version.\n * @param store - the resolved store facts for `artifact.versionId`.\n * @returns the bounded listing entry.\n */\nfunction capturedArtifactValue(\n  artifact: ScienceArtifactVersion,\n  store: ScienceArtifactStoreFacts,\n): InferValue<typeof capturedArtifactSchema> {\n  return {\n    ...scienceArtifactValueFields(artifact, store),\n    versionId: String(artifact.versionId),\n    ...store.lineage === undefined ? {} : { lineage: store.lineage },\n  }\n}\n\n/** Flatten one captured artifact's bounded listing entry into its Client presentation reference. */\nfunction capturedArtifactPresentationItem(artifact: InferValue<typeof capturedArtifactSchema>): ScienceArtifactPresentationItem {\n  return {\n    artifactId: artifact.artifactId,\n    logicalName: artifact.logicalName,\n    version: artifact.version,\n    title: artifact.title,\n    content: {\n      versionId: artifact.versionId,\n      mediaType: artifact.mediaType as ScienceArtifactMediaType,\n      byteCount: artifact.bytes,\n    },\n  }\n}\n\n/**\n * Flatten a Runtime result into the tool's bounded canonical value.\n * `content_origin`/`curated`/`mediaType`/`bytes` for each captured artifact\n * come from the store — the sole authority for those facts since the T1/T2\n * artifact-authority migration — through `resolveStore`.\n * @param result - the durably committed run result from `ctx.scienceRuntime.startRun(...).done`.\n * @param resolveStore - resolves each captured artifact's store facts.\n * @returns the bounded structured value the tool returns.\n */\nexport async function runValueFromResult(\n  result: ScienceRunResult,\n  resolveStore: ResolveArtifactStoreFacts,\n): Promise<ScienceRunValue> {\n  const { terminal, capture } = result\n  return {\n    status: terminal.status,\n    runId: String(terminal.runId),\n    startedAt: terminal.startedAt,\n    finishedAt: terminal.finishedAt,\n    ...terminal.failureCode === undefined ? {} : { failureCode: terminal.failureCode },\n    ...terminal.failureMessage === undefined ? {} : { failureMessage: terminal.failureMessage },\n    stdout: result.stdout,\n    stderr: result.stderr,\n    ...result.captureFailure === undefined ? {} : { captureFailure: result.captureFailure },\n    ...capture === undefined ? {} : {\n      capturedArtifacts: await Promise.all(\n        capture.captured.map(async artifact => capturedArtifactValue(artifact, await resolveStore(artifact))),\n      ),\n      ...capture.skippedRasterPaths.length > 0 ? { skippedRaster: [...capture.skippedRasterPaths] } : {},\n      ...capture.skippedOversizedCount > 0 ? { captureSkippedOversizedCount: capture.skippedOversizedCount } : {},\n      ...capture.truncatedPerRun ? { captureTruncatedPerRun: true } : {},\n      ...capture.truncatedPerSession ? { captureTruncatedPerSession: true } : {},\n    },\n  }\n}\n\n/**\n * Whether this run's terminal is the first one recorded under its own\n * kernel epoch for its language, following an earlier epoch for that same\n * language — the only case the model needs told: the kernel that ran this\n * source is not the one that ran earlier calls, so whatever those calls left\n * in memory is gone. Absent for every other